// Auto-generated templates from @noetic-ui/react source

export interface TemplateFile {
  filename: string;
  content: string;
}

export const COMPONENT_TEMPLATES: Record<string, TemplateFile> = {
  "cn": {
    filename: "cn.ts",
    content: "import { type ClassValue, clsx } from 'clsx';\nimport { twMerge } from 'tailwind-merge';\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n",
  },
  "types": {
    filename: "types.ts",
    content: "import type { ReactNode } from 'react';\n\nexport type Role = 'user' | 'assistant' | 'system' | 'tool' | 'agent';\n\nexport interface ModelInfo {\n  id: string;\n  name: string;\n  provider?: 'openai' | 'anthropic' | 'google' | 'meta' | 'deepseek' | 'mistral' | 'local' | string;\n  icon?: ReactNode;\n  contextWindow?: number;\n  description?: string;\n  speed?: 'fast' | 'moderate' | 'slow';\n  reasoningEffort?: 'low' | 'medium' | 'high';\n}\n\nexport interface TokenUsage {\n  prompt?: number;\n  completion?: number;\n  total?: number;\n  costUsd?: number;\n}\n\nexport interface ThoughtStep {\n  id: string;\n  title: string;\n  status: 'pending' | 'running' | 'completed' | 'failed';\n  durationMs?: number;\n}\n\nexport interface ThoughtProcess {\n  id: string;\n  title?: string;\n  content: string;\n  durationMs?: number;\n  isStreaming?: boolean;\n  tokens?: number;\n  steps?: ThoughtStep[];\n}\n\nexport type ToolStatus = 'idle' | 'running' | 'success' | 'error' | 'cancelled' | 'awaiting_approval';\n\nexport interface ToolCall {\n  id: string;\n  name: string;\n  args: Record<string, unknown> | string;\n  result?: unknown;\n  status: ToolStatus;\n  durationMs?: number;\n  error?: string;\n  requiresApproval?: boolean;\n  approvalSeverity?: 'low' | 'medium' | 'critical';\n  approved?: boolean;\n}\n\nexport type ArtifactType = 'code' | 'markdown' | 'diff' | 'html' | 'svg' | 'table' | 'json' | 'image';\n\nexport interface Artifact {\n  id: string;\n  title: string;\n  type: ArtifactType;\n  content: string;\n  language?: string;\n  filename?: string;\n  version?: number;\n  description?: string;\n  isLivePreviewable?: boolean;\n}\n\nexport type StepStatus = 'pending' | 'in_progress' | 'completed' | 'failed' | 'skipped';\n\nexport interface AgentPlanStep {\n  id: string;\n  title: string;\n  description?: string;\n  status: StepStatus;\n  subtasks?: AgentPlanStep[];\n  toolCallId?: string;\n}\n\nexport interface AgentPlan {\n  id: string;\n  title: string;\n  description?: string;\n  status: 'draft' | 'running' | 'completed' | 'failed';\n  steps: AgentPlanStep[];\n  progressPercent?: number;\n}\n\nexport interface FileAttachment {\n  id: string;\n  name: string;\n  size: number;\n  type: string;\n  url?: string;\n  previewUrl?: string;\n  status: 'uploading' | 'ready' | 'error';\n  progress?: number;\n}\n\nexport interface AgentMessage {\n  id: string;\n  role: Role;\n  content: string;\n  createdAt?: Date | string | number;\n  name?: string;\n  avatar?: string;\n  model?: ModelInfo;\n  tokens?: TokenUsage;\n  latencyMs?: number;\n  status?: 'idle' | 'streaming' | 'completed' | 'error';\n  thoughts?: ThoughtProcess[];\n  toolCalls?: ToolCall[];\n  artifacts?: Artifact[];\n  plan?: AgentPlan;\n  attachments?: FileAttachment[];\n  branches?: AgentMessage[][];\n  selectedBranchIndex?: number;\n}\n",
  },
  "ReasoningAccordion": {
    filename: "ReasoningAccordion.tsx",
    content: "import React, { useState, useEffect } from 'react';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport { Sparkles, ChevronDown, Clock, Cpu, CheckCircle2, AlertCircle, Loader2, Copy, Check } from 'lucide-react';\nimport { cn } from './cn';\nimport type { ThoughtProcess } from './types';\n\nexport interface ReasoningAccordionProps {\n  thought: ThoughtProcess;\n  defaultExpanded?: boolean;\n  className?: string;\n  onCopy?: (content: string) => void;\n}\n\nexport const ReasoningAccordion: React.FC<ReasoningAccordionProps> = ({\n  thought,\n  defaultExpanded = false,\n  className,\n  onCopy,\n}) => {\n  const [isExpanded, setIsExpanded] = useState(defaultExpanded || !!thought.isStreaming);\n  const [copied, setCopied] = useState(false);\n  const [elapsedSeconds, setElapsedSeconds] = useState(\n    thought.durationMs ? (thought.durationMs / 1000).toFixed(1) : '0.0'\n  );\n\n  // Auto-expand when streaming starts\n  useEffect(() => {\n    if (thought.isStreaming) {\n      setIsExpanded(true);\n    }\n  }, [thought.isStreaming]);\n\n  // Live timer tick when streaming\n  useEffect(() => {\n    if (!thought.isStreaming) {\n      if (thought.durationMs) {\n        setElapsedSeconds((thought.durationMs / 1000).toFixed(1));\n      }\n      return;\n    }\n\n    const start = Date.now();\n    const interval = setInterval(() => {\n      const elapsed = ((Date.now() - start) / 1000).toFixed(1);\n      setElapsedSeconds(elapsed);\n    }, 100);\n\n    return () => clearInterval(interval);\n  }, [thought.isStreaming, thought.durationMs]);\n\n  const handleCopy = (e: React.MouseEvent) => {\n    e.stopPropagation();\n    navigator.clipboard.writeText(thought.content);\n    setCopied(true);\n    if (onCopy) onCopy(thought.content);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  return (\n    <div\n      className={cn(\n        'group my-2 rounded-xl border border-border/50 bg-secondary/30 backdrop-blur-sm transition-all duration-200 overflow-hidden',\n        thought.isStreaming && 'border-primary/30 bg-primary/5 shadow-sm shadow-primary/5',\n        className\n      )}\n    >\n      {/* Header Bar */}\n      <div\n        role=\"button\"\n        tabIndex={0}\n        onClick={() => setIsExpanded(!isExpanded)}\n        onKeyDown={(e) => {\n          if (e.key === 'Enter' || e.key === ' ') {\n            e.preventDefault();\n            setIsExpanded(!isExpanded);\n          }\n        }}\n        className=\"w-full flex items-center justify-between px-3.5 py-2.5 text-left text-xs text-muted-foreground hover:text-foreground transition-colors cursor-pointer select-none\"\n      >\n        <div className=\"flex items-center gap-2 min-w-0\">\n          <div\n            className={cn(\n              'flex h-5 w-5 items-center justify-center rounded-md bg-primary/10 text-primary',\n              thought.isStreaming && 'animate-pulse'\n            )}\n          >\n            {thought.isStreaming ? (\n              <Loader2 className=\"h-3 w-3 animate-spin\" />\n            ) : (\n              <Sparkles className=\"h-3 w-3\" />\n            )}\n          </div>\n\n          <span className=\"font-medium text-foreground/90 truncate\">\n            {thought.title || (thought.isStreaming ? 'Thinking...' : 'Reasoning Process')}\n          </span>\n\n          {/* Badges */}\n          <div className=\"flex items-center gap-1.5 ml-1\">\n            <span className=\"inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full bg-background/80 text-[10px] text-muted-foreground border border-border/40 font-mono\">\n              <Clock className=\"h-2.5 w-2.5\" />\n              {elapsedSeconds}s\n            </span>\n\n            {thought.tokens && (\n              <span className=\"hidden sm:inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full bg-background/80 text-[10px] text-muted-foreground border border-border/40 font-mono\">\n                <Cpu className=\"h-2.5 w-2.5\" />\n                {thought.tokens} tokens\n              </span>\n            )}\n          </div>\n        </div>\n\n        <div className=\"flex items-center gap-2 flex-shrink-0\">\n          {isExpanded && thought.content && (\n            <button\n              type=\"button\"\n              onClick={handleCopy}\n              className=\"p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-background/80 transition-colors\"\n              title=\"Copy reasoning markdown\"\n            >\n              {copied ? (\n                <Check className=\"h-3 w-3 text-emerald-500\" />\n              ) : (\n                <Copy className=\"h-3 w-3\" />\n              )}\n            </button>\n          )}\n\n          <motion.div\n            animate={{ rotate: isExpanded ? 180 : 0 }}\n            transition={{ duration: 0.2 }}\n          >\n            <ChevronDown className=\"h-3.5 w-3.5\" />\n          </motion.div>\n        </div>\n      </div>\n\n      {/* Expanded Content */}\n      <AnimatePresence initial={false}>\n        {isExpanded && (\n          <motion.div\n            initial={{ height: 0, opacity: 0 }}\n            animate={{ height: 'auto', opacity: 1 }}\n            exit={{ height: 0, opacity: 0 }}\n            transition={{ duration: 0.22, ease: 'easeInOut' }}\n          >\n            <div className=\"border-t border-border/40 px-4 py-3 text-xs leading-relaxed text-muted-foreground/90 font-mono bg-background/30 select-text\">\n              {/* Step progression if available */}\n              {thought.steps && thought.steps.length > 0 && (\n                <div className=\"mb-3 space-y-1.5 pb-2.5 border-b border-border/30\">\n                  {thought.steps.map((step) => (\n                    <div key={step.id} className=\"flex items-center gap-2 text-[11px]\">\n                      {step.status === 'completed' && (\n                        <CheckCircle2 className=\"h-3 w-3 text-emerald-500 flex-shrink-0\" />\n                      )}\n                      {step.status === 'running' && (\n                        <Loader2 className=\"h-3 w-3 text-primary animate-spin flex-shrink-0\" />\n                      )}\n                      {step.status === 'failed' && (\n                        <AlertCircle className=\"h-3 w-3 text-rose-500 flex-shrink-0\" />\n                      )}\n                      {step.status === 'pending' && (\n                        <div className=\"h-1.5 w-1.5 rounded-full bg-muted-foreground/40 ml-1 mr-0.5 flex-shrink-0\" />\n                      )}\n                      <span\n                        className={cn(\n                          'truncate font-sans',\n                          step.status === 'running' && 'text-foreground font-medium',\n                          step.status === 'completed' && 'text-muted-foreground line-through opacity-70'\n                        )}\n                      >\n                        {step.title}\n                      </span>\n                    </div>\n                  ))}\n                </div>\n              )}\n\n              {/* Main Thought Stream */}\n              <div className=\"whitespace-pre-wrap font-sans text-xs text-foreground/80 leading-relaxed max-h-72 overflow-y-auto pr-1\">\n                {thought.content || (\n                  <span className=\"italic text-muted-foreground/60\">Contemplating approach...</span>\n                )}\n                {thought.isStreaming && (\n                  <span className=\"inline-block h-3 w-1.5 bg-primary ml-1 animate-pulse align-middle\" />\n                )}\n              </div>\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n};\n",
  },
  "ToolCallCard": {
    filename: "ToolCallCard.tsx",
    content: "import React, { useState } from 'react';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport {\n  Terminal,\n  Globe,\n  FileText,\n  FileCode,\n  Database,\n  Code2,\n  Wrench,\n  ChevronDown,\n  CheckCircle2,\n  AlertCircle,\n  Clock,\n  Loader2,\n  Copy,\n  Check,\n  ShieldAlert,\n  Play,\n  XCircle,\n} from 'lucide-react';\nimport { cn } from './cn';\nimport type { ToolCall } from './types';\n\nexport interface ToolCallCardProps {\n  toolCall: ToolCall;\n  defaultExpanded?: boolean;\n  onApprove?: (toolCallId: string) => void;\n  onReject?: (toolCallId: string) => void;\n  className?: string;\n}\n\nconst getToolIcon = (name: string) => {\n  const lower = name.toLowerCase();\n  if (lower.includes('bash') || lower.includes('command') || lower.includes('terminal') || lower.includes('exec')) {\n    return <Terminal className=\"h-3.5 w-3.5\" />;\n  }\n  if (lower.includes('web') || lower.includes('search') || lower.includes('browser') || lower.includes('url')) {\n    return <Globe className=\"h-3.5 w-3.5\" />;\n  }\n  if (lower.includes('read') || lower.includes('view') || lower.includes('cat') || lower.includes('find')) {\n    return <FileText className=\"h-3.5 w-3.5\" />;\n  }\n  if (lower.includes('edit') || lower.includes('write') || lower.includes('replace') || lower.includes('patch')) {\n    return <FileCode className=\"h-3.5 w-3.5\" />;\n  }\n  if (lower.includes('sql') || lower.includes('db') || lower.includes('database') || lower.includes('postgres')) {\n    return <Database className=\"h-3.5 w-3.5\" />;\n  }\n  if (lower.includes('python') || lower.includes('code') || lower.includes('run')) {\n    return <Code2 className=\"h-3.5 w-3.5\" />;\n  }\n  return <Wrench className=\"h-3.5 w-3.5\" />;\n};\n\nexport const ToolCallCard: React.FC<ToolCallCardProps> = ({\n  toolCall,\n  defaultExpanded = false,\n  onApprove,\n  onReject,\n  className,\n}) => {\n  const [isExpanded, setIsExpanded] = useState(defaultExpanded || toolCall.status === 'awaiting_approval');\n  const [activeTab, setActiveTab] = useState<'output' | 'args' | 'raw'>('output');\n  const [copied, setCopied] = useState(false);\n\n  const formattedArgs =\n    typeof toolCall.args === 'string'\n      ? toolCall.args\n      : JSON.stringify(toolCall.args, null, 2);\n\n  const formattedResult =\n    typeof toolCall.result === 'string'\n      ? toolCall.result\n      : JSON.stringify(toolCall.result, null, 2);\n\n  const handleCopy = (e: React.MouseEvent, text: string) => {\n    e.stopPropagation();\n    navigator.clipboard.writeText(text);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  return (\n    <div\n      className={cn(\n        'my-2 rounded-xl border bg-card/60 backdrop-blur-sm transition-all duration-200 overflow-hidden shadow-sm',\n        toolCall.status === 'running' && 'border-cyan-500/40 bg-cyan-500/5 shadow-cyan-500/5',\n        toolCall.status === 'awaiting_approval' && 'border-amber-500/40 bg-amber-500/5 shadow-amber-500/5',\n        toolCall.status === 'error' && 'border-rose-500/30 bg-rose-500/5',\n        toolCall.status === 'success' && 'border-border/60 hover:border-border',\n        className\n      )}\n    >\n      {/* Card Header */}\n      <div\n        onClick={() => setIsExpanded(!isExpanded)}\n        className=\"flex items-center justify-between px-3.5 py-2.5 cursor-pointer select-none text-xs text-muted-foreground hover:text-foreground transition-colors\"\n      >\n        <div className=\"flex items-center gap-2.5 min-w-0\">\n          {/* Tool Icon */}\n          <div\n            className={cn(\n              'flex h-6 w-6 items-center justify-center rounded-lg border text-foreground/80 transition-colors',\n              toolCall.status === 'running' && 'border-cyan-500/30 bg-cyan-500/10 text-cyan-500',\n              toolCall.status === 'awaiting_approval' && 'border-amber-500/30 bg-amber-500/10 text-amber-500',\n              toolCall.status === 'error' && 'border-rose-500/30 bg-rose-500/10 text-rose-500',\n              toolCall.status === 'success' && 'border-border/60 bg-secondary/50 text-foreground/80'\n            )}\n          >\n            {getToolIcon(toolCall.name)}\n          </div>\n\n          {/* Tool Name & Quick Args */}\n          <div className=\"flex items-center gap-2 min-w-0\">\n            <span className=\"font-mono font-medium text-foreground text-xs\">\n              {toolCall.name}\n            </span>\n\n            {/* Quick summary parameter */}\n            {typeof toolCall.args === 'object' && toolCall.args !== null && (\n              <span className=\"hidden md:inline-block font-mono text-[11px] text-muted-foreground/70 truncate max-w-xs\">\n                {Object.entries(toolCall.args)[0]\n                  ? `${Object.entries(toolCall.args)[0][0]}: \"${String(Object.entries(toolCall.args)[0][1]).slice(0, 30)}...\"`\n                  : ''}\n              </span>\n            )}\n          </div>\n        </div>\n\n        {/* Status Badge & Actions */}\n        <div className=\"flex items-center gap-2 flex-shrink-0\">\n          {toolCall.status === 'running' && (\n            <span className=\"inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-cyan-500/15 text-[10px] text-cyan-800 dark:text-cyan-300 border border-cyan-500/30 font-medium\">\n              <Loader2 className=\"h-2.5 w-2.5 animate-spin\" />\n              Running\n            </span>\n          )}\n\n          {toolCall.status === 'awaiting_approval' && (\n            <span className=\"inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-500/20 text-[10px] text-amber-950 dark:text-amber-300 border border-amber-500/40 font-semibold animate-pulse\">\n              <ShieldAlert className=\"h-2.5 w-2.5\" />\n              Requires Approval\n            </span>\n          )}\n\n          {toolCall.status === 'success' && (\n            <span className=\"inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-emerald-500/15 text-[10px] text-emerald-800 dark:text-emerald-300 border border-emerald-500/30 font-medium\">\n              <CheckCircle2 className=\"h-2.5 w-2.5\" />\n              Completed\n            </span>\n          )}\n\n          {toolCall.status === 'error' && (\n            <span className=\"inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-rose-500/15 text-[10px] text-rose-800 dark:text-rose-300 border border-rose-500/30 font-medium\">\n              <AlertCircle className=\"h-2.5 w-2.5\" />\n              Failed\n            </span>\n          )}\n\n          {toolCall.durationMs !== undefined && (\n            <span className=\"hidden sm:inline-flex items-center gap-1 text-[10px] text-muted-foreground font-mono\">\n              <Clock className=\"h-2.5 w-2.5\" />\n              {toolCall.durationMs}ms\n            </span>\n          )}\n\n          <motion.div\n            animate={{ rotate: isExpanded ? 180 : 0 }}\n            transition={{ duration: 0.2 }}\n            className=\"text-muted-foreground hover:text-foreground\"\n          >\n            <ChevronDown className=\"h-3.5 w-3.5\" />\n          </motion.div>\n        </div>\n      </div>\n\n      {/* Human In The Loop Approval Banner */}\n      {toolCall.status === 'awaiting_approval' && (\n        <div className=\"px-3.5 py-2.5 bg-amber-500/10 border-t border-b border-amber-500/20 flex flex-col sm:flex-row sm:items-center justify-between gap-2.5\">\n          <div className=\"flex items-center gap-2 text-xs text-amber-700 dark:text-amber-300\">\n            <ShieldAlert className=\"h-4 w-4 flex-shrink-0\" />\n            <span>Agent wants to execute this action. Confirm to proceed.</span>\n          </div>\n          <div className=\"flex items-center gap-2 self-end sm:self-auto\">\n            <button\n              type=\"button\"\n              onClick={(e) => {\n                e.stopPropagation();\n                if (onReject) onReject(toolCall.id);\n              }}\n              className=\"inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-secondary border border-border/60 transition-colors\"\n            >\n              <XCircle className=\"h-3 w-3\" />\n              Reject\n            </button>\n            <button\n              type=\"button\"\n              onClick={(e) => {\n                e.stopPropagation();\n                if (onApprove) onApprove(toolCall.id);\n              }}\n              className=\"inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium bg-amber-500 text-amber-950 hover:bg-amber-400 font-semibold transition-colors shadow-sm\"\n            >\n              <Play className=\"h-3 w-3 fill-current\" />\n              Approve\n            </button>\n          </div>\n        </div>\n      )}\n\n      {/* Expanded Details Body */}\n      <AnimatePresence initial={false}>\n        {isExpanded && (\n          <motion.div\n            initial={{ height: 0, opacity: 0 }}\n            animate={{ height: 'auto', opacity: 1 }}\n            exit={{ height: 0, opacity: 0 }}\n            transition={{ duration: 0.22, ease: 'easeInOut' }}\n          >\n            <div className=\"border-t border-border/40 bg-secondary/20\">\n              {/* Tab Navigation */}\n              <div className=\"flex items-center justify-between px-3.5 py-1.5 border-b border-border/30 bg-background/50 text-[11px]\">\n                <div className=\"flex items-center gap-1\">\n                  <button\n                    type=\"button\"\n                    onClick={() => setActiveTab('output')}\n                    className={cn(\n                      'px-2 py-0.5 rounded-md font-medium transition-colors',\n                      activeTab === 'output'\n                        ? 'bg-secondary text-foreground'\n                        : 'text-muted-foreground hover:text-foreground'\n                    )}\n                  >\n                    Output\n                  </button>\n                  <button\n                    type=\"button\"\n                    onClick={() => setActiveTab('args')}\n                    className={cn(\n                      'px-2 py-0.5 rounded-md font-medium transition-colors',\n                      activeTab === 'args'\n                        ? 'bg-secondary text-foreground'\n                        : 'text-muted-foreground hover:text-foreground'\n                    )}\n                  >\n                    Arguments\n                  </button>\n                  <button\n                    type=\"button\"\n                    onClick={() => setActiveTab('raw')}\n                    className={cn(\n                      'px-2 py-0.5 rounded-md font-medium transition-colors',\n                      activeTab === 'raw'\n                        ? 'bg-secondary text-foreground'\n                        : 'text-muted-foreground hover:text-foreground'\n                    )}\n                  >\n                    Raw JSON\n                  </button>\n                </div>\n\n                {/* Copy current view */}\n                <button\n                  type=\"button\"\n                  onClick={(e) =>\n                    handleCopy(\n                      e,\n                      activeTab === 'output'\n                        ? formattedResult\n                        : activeTab === 'args'\n                        ? formattedArgs\n                        : JSON.stringify(toolCall, null, 2)\n                    )\n                  }\n                  className=\"p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n                  title=\"Copy snippet\"\n                >\n                  {copied ? (\n                    <Check className=\"h-3 w-3 text-emerald-500\" />\n                  ) : (\n                    <Copy className=\"h-3 w-3\" />\n                  )}\n                </button>\n              </div>\n\n              {/* Tab Content Panes */}\n              <div className=\"p-3 font-mono text-[11px] leading-relaxed max-h-80 overflow-y-auto select-text\">\n                {activeTab === 'output' && (\n                  <div>\n                    {toolCall.status === 'running' && (\n                      <div className=\"flex items-center gap-2 text-muted-foreground py-2\">\n                        <Loader2 className=\"h-3.5 w-3.5 animate-spin text-cyan-500\" />\n                        <span>Awaiting tool execution result...</span>\n                      </div>\n                    )}\n                    {toolCall.error && (\n                      <div className=\"p-2.5 rounded-lg bg-rose-500/10 border border-rose-500/20 text-rose-600 dark:text-rose-400 whitespace-pre-wrap\">\n                        {toolCall.error}\n                      </div>\n                    )}\n                    {toolCall.result !== undefined && !toolCall.error && (\n                      <pre className=\"text-foreground/90 whitespace-pre-wrap break-all\">\n                        {formattedResult}\n                      </pre>\n                    )}\n                    {toolCall.result === undefined && !toolCall.error && toolCall.status !== 'running' && (\n                      <span className=\"text-muted-foreground italic\">No output returned.</span>\n                    )}\n                  </div>\n                )}\n\n                {activeTab === 'args' && (\n                  <pre className=\"text-foreground/90 whitespace-pre-wrap break-all\">\n                    {formattedArgs}\n                  </pre>\n                )}\n\n                {activeTab === 'raw' && (\n                  <pre className=\"text-foreground/80 whitespace-pre-wrap break-all\">\n                    {JSON.stringify(toolCall, null, 2)}\n                  </pre>\n                )}\n              </div>\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n};\n",
  },
  "AgentPlanView": {
    filename: "AgentPlanView.tsx",
    content: "import React, { useState } from 'react';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport {\n  ListTodo,\n  CheckCircle2,\n  Circle,\n  Loader2,\n  AlertCircle,\n  ChevronDown,\n  CornerDownRight,\n  MinusCircle,\n} from 'lucide-react';\nimport { cn } from './cn';\nimport type { AgentPlan, AgentPlanStep, StepStatus } from './types';\n\nexport interface AgentPlanViewProps {\n  plan: AgentPlan;\n  defaultExpanded?: boolean;\n  onStepClick?: (step: AgentPlanStep) => void;\n  className?: string;\n}\n\nconst getStepIcon = (status: StepStatus) => {\n  switch (status) {\n    case 'completed':\n      return <CheckCircle2 className=\"h-3.5 w-3.5 text-emerald-500 flex-shrink-0\" />;\n    case 'in_progress':\n      return <Loader2 className=\"h-3.5 w-3.5 text-primary animate-spin flex-shrink-0\" />;\n    case 'failed':\n      return <AlertCircle className=\"h-3.5 w-3.5 text-rose-500 flex-shrink-0\" />;\n    case 'skipped':\n      return <MinusCircle className=\"h-3.5 w-3.5 text-muted-foreground/60 flex-shrink-0\" />;\n    case 'pending':\n    default:\n      return <Circle className=\"h-3.5 w-3.5 text-muted-foreground/40 flex-shrink-0\" />;\n  }\n};\n\nexport const AgentPlanView: React.FC<AgentPlanViewProps> = ({\n  plan,\n  defaultExpanded = true,\n  onStepClick,\n  className,\n}) => {\n  const [isExpanded, setIsExpanded] = useState(defaultExpanded);\n\n  // Calculate completed count and progress percentage\n  const totalSteps = plan.steps.reduce(\n    (acc, s) => acc + 1 + (s.subtasks ? s.subtasks.length : 0),\n    0\n  );\n\n  const completedSteps = plan.steps.reduce((acc, s) => {\n    let count = s.status === 'completed' ? 1 : 0;\n    if (s.subtasks) {\n      count += s.subtasks.filter((sub) => sub.status === 'completed').length;\n    }\n    return acc + count;\n  }, 0);\n\n  const progressPercent =\n    plan.progressPercent !== undefined\n      ? plan.progressPercent\n      : totalSteps > 0\n      ? Math.round((completedSteps / totalSteps) * 100)\n      : 0;\n\n  return (\n    <div\n      className={cn(\n        'my-3 rounded-xl border border-border/60 bg-card/60 backdrop-blur-sm overflow-hidden shadow-sm transition-all',\n        plan.status === 'running' && 'border-primary/30',\n        className\n      )}\n    >\n      {/* Header */}\n      <button\n        type=\"button\"\n        onClick={() => setIsExpanded(!isExpanded)}\n        className=\"w-full flex items-center justify-between px-4 py-3 text-left hover:bg-secondary/40 transition-colors\"\n      >\n        <div className=\"flex items-center gap-2.5 min-w-0\">\n          <div className=\"flex h-6 w-6 items-center justify-center rounded-lg bg-primary/10 text-primary\">\n            <ListTodo className=\"h-3.5 w-3.5\" />\n          </div>\n\n          <div className=\"min-w-0\">\n            <div className=\"flex items-center gap-2\">\n              <span className=\"text-xs font-semibold text-foreground truncate\">\n                {plan.title || 'Execution Plan'}\n              </span>\n              <span className=\"text-[10px] font-mono text-muted-foreground px-1.5 py-0.5 rounded-full bg-secondary border border-border/40\">\n                {completedSteps}/{totalSteps}\n              </span>\n            </div>\n          </div>\n        </div>\n\n        <div className=\"flex items-center gap-3 flex-shrink-0\">\n          {/* Progress Pill */}\n          <div className=\"hidden sm:flex items-center gap-2\">\n            <div className=\"w-20 h-1.5 rounded-full bg-secondary overflow-hidden\">\n              <motion.div\n                className=\"h-full bg-primary rounded-full\"\n                initial={{ width: 0 }}\n                animate={{ width: `${progressPercent}%` }}\n                transition={{ duration: 0.4 }}\n              />\n            </div>\n            <span className=\"text-[10px] font-mono text-muted-foreground font-medium\">\n              {progressPercent}%\n            </span>\n          </div>\n\n          <motion.div\n            animate={{ rotate: isExpanded ? 180 : 0 }}\n            transition={{ duration: 0.2 }}\n            className=\"text-muted-foreground\"\n          >\n            <ChevronDown className=\"h-4 w-4\" />\n          </motion.div>\n        </div>\n      </button>\n\n      {/* Steps List */}\n      <AnimatePresence initial={false}>\n        {isExpanded && (\n          <motion.div\n            initial={{ height: 0, opacity: 0 }}\n            animate={{ height: 'auto', opacity: 1 }}\n            exit={{ height: 0, opacity: 0 }}\n            transition={{ duration: 0.22, ease: 'easeInOut' }}\n          >\n            <div className=\"border-t border-border/40 px-4 py-3 bg-secondary/10 space-y-2\">\n              {plan.description && (\n                <p className=\"text-xs text-muted-foreground mb-3 leading-relaxed\">\n                  {plan.description}\n                </p>\n              )}\n\n              <div className=\"space-y-1.5\">\n                {plan.steps.map((step, idx) => (\n                  <div key={step.id || idx} className=\"space-y-1\">\n                    {/* Main Step Row */}\n                    <div\n                      onClick={() => onStepClick && onStepClick(step)}\n                      className={cn(\n                        'flex items-start gap-2.5 p-2 rounded-lg transition-colors text-xs select-none',\n                        onStepClick ? 'cursor-pointer hover:bg-secondary/60' : '',\n                        step.status === 'in_progress' && 'bg-primary/10 border border-primary/20 font-medium'\n                      )}\n                    >\n                      <div className=\"mt-0.5\">{getStepIcon(step.status)}</div>\n                      <div className=\"min-w-0 flex-1\">\n                        <div className=\"flex items-center justify-between gap-2\">\n                          <span\n                            className={cn(\n                              'text-foreground/90 leading-snug',\n                              step.status === 'completed' && 'line-through text-muted-foreground/70',\n                              step.status === 'in_progress' && 'text-foreground font-semibold'\n                            )}\n                          >\n                            {step.title}\n                          </span>\n                          {step.status === 'in_progress' && (\n                            <span className=\"text-[10px] uppercase font-mono px-1.5 py-0.5 rounded bg-primary text-primary-foreground font-bold tracking-wider shadow-2xs\">\n                              Active\n                            </span>\n                          )}\n                        </div>\n                        {step.description && (\n                          <p className=\"text-[11px] text-muted-foreground mt-0.5 line-clamp-2 leading-relaxed\">\n                            {step.description}\n                          </p>\n                        )}\n                      </div>\n                    </div>\n\n                    {/* Subtasks if any */}\n                    {step.subtasks && step.subtasks.length > 0 && (\n                      <div className=\"pl-6 space-y-1 border-l-2 border-border/40 ml-4 py-1\">\n                        {step.subtasks.map((sub, subIdx) => (\n                          <div\n                            key={sub.id || subIdx}\n                            className=\"flex items-center gap-2 p-1.5 rounded-md hover:bg-secondary/40 text-[11px] text-muted-foreground\"\n                          >\n                            <CornerDownRight className=\"h-3 w-3 text-muted-foreground/40\" />\n                            {getStepIcon(sub.status)}\n                            <span\n                              className={cn(\n                                sub.status === 'completed' && 'line-through text-muted-foreground/60',\n                                sub.status === 'in_progress' && 'text-foreground font-medium'\n                              )}\n                            >\n                              {sub.title}\n                            </span>\n                          </div>\n                        ))}\n                      </div>\n                    )}\n                  </div>\n                ))}\n              </div>\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n};\n",
  },
  "AgentSwarmView": {
    filename: "AgentSwarmView.tsx",
    content: "import React from 'react';\nimport { Bot, ArrowRight, CheckCircle2, Loader2, AlertCircle, Users } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface SwarmAgent {\n  id: string;\n  name: string;\n  role: string;\n  status: 'idle' | 'working' | 'completed' | 'failed';\n  avatar?: string;\n  currentTask?: string;\n  progress?: number;\n}\n\nexport interface AgentSwarmViewProps {\n  agents: SwarmAgent[];\n  activeAgentId?: string;\n  onSelectAgent?: (agentId: string) => void;\n  className?: string;\n}\n\nexport const AgentSwarmView: React.FC<AgentSwarmViewProps> = ({\n  agents,\n  activeAgentId,\n  onSelectAgent,\n  className,\n}) => {\n  return (\n    <div\n      className={cn(\n        'my-3 p-3.5 rounded-xl border border-border/60 bg-card/60 backdrop-blur-sm shadow-sm',\n        className\n      )}\n    >\n      <div className=\"flex items-center justify-between mb-3\">\n        <div className=\"flex items-center gap-2\">\n          <div className=\"flex h-5 w-5 items-center justify-center rounded-md bg-primary/10 text-primary\">\n            <Users className=\"h-3 w-3\" />\n          </div>\n          <span className=\"text-xs font-semibold text-foreground\">\n            Multi-Agent Swarm ({agents.length})\n          </span>\n        </div>\n        <span className=\"text-[10px] text-muted-foreground font-mono\">\n          {agents.filter((a) => a.status === 'working').length} active\n        </span>\n      </div>\n\n      <div className=\"grid grid-cols-1 sm:grid-cols-2 gap-2.5\">\n        {agents.map((agent) => {\n          const isActive = agent.id === activeAgentId;\n          return (\n            <div\n              key={agent.id}\n              onClick={() => onSelectAgent && onSelectAgent(agent.id)}\n              className={cn(\n                'p-2.5 rounded-lg border border-border/40 bg-secondary/30 transition-all text-xs',\n                onSelectAgent ? 'cursor-pointer hover:border-primary/40 hover:bg-secondary/60' : '',\n                isActive && 'border-primary/60 bg-primary/10 shadow-sm shadow-primary/10',\n                agent.status === 'working' && 'border-primary/30'\n              )}\n            >\n              <div className=\"flex items-center justify-between gap-2\">\n                <div className=\"flex items-center gap-2 min-w-0\">\n                  <div className=\"relative\">\n                    <div className=\"flex h-7 w-7 items-center justify-center rounded-full bg-secondary border border-border/60 text-foreground font-semibold text-xs\">\n                      {agent.avatar ? (\n                        <img\n                          src={agent.avatar}\n                          alt={agent.name}\n                          className=\"h-full w-full rounded-full object-cover\"\n                        />\n                      ) : (\n                        <Bot className=\"h-3.5 w-3.5 text-primary\" />\n                      )}\n                    </div>\n                    {agent.status === 'working' && (\n                      <span className=\"absolute -top-0.5 -right-0.5 flex h-2.5 w-2.5\">\n                        <span className=\"animate-ping absolute inline-flex h-full w-full rounded-full bg-primary opacity-75\" />\n                        <span className=\"relative inline-flex rounded-full h-2.5 w-2.5 bg-primary\" />\n                      </span>\n                    )}\n                  </div>\n\n                  <div className=\"min-w-0\">\n                    <p className=\"font-semibold text-foreground text-xs truncate\">\n                      {agent.name}\n                    </p>\n                    <p className=\"text-[10px] text-muted-foreground truncate\">\n                      {agent.role}\n                    </p>\n                  </div>\n                </div>\n\n                {/* Status Indicator */}\n                <div className=\"flex-shrink-0\">\n                  {agent.status === 'working' && (\n                    <span className=\"inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-primary text-primary-foreground font-bold font-mono text-[10px] shadow-2xs\">\n                      <Loader2 className=\"h-2.5 w-2.5 animate-spin\" />\n                      Working\n                    </span>\n                  )}\n                  {agent.status === 'completed' && (\n                    <span className=\"inline-flex items-center gap-1 text-[10px] text-emerald-800 dark:text-emerald-300 font-mono font-medium\">\n                      <CheckCircle2 className=\"h-2.5 w-2.5\" />\n                      Done\n                    </span>\n                  )}\n                  {agent.status === 'failed' && (\n                    <span className=\"inline-flex items-center gap-1 text-[10px] text-rose-800 dark:text-rose-300 font-mono font-medium\">\n                      <AlertCircle className=\"h-2.5 w-2.5\" />\n                      Error\n                    </span>\n                  )}\n                  {agent.status === 'idle' && (\n                    <span className=\"text-[10px] text-muted-foreground font-mono\">\n                      Idle\n                    </span>\n                  )}\n                </div>\n              </div>\n\n              {agent.currentTask && (\n                <div className=\"mt-2 pt-2 border-t border-border/40 text-[11px] text-foreground/80 flex items-center gap-1.5 truncate\">\n                  <ArrowRight className=\"h-2.5 w-2.5 text-muted-foreground/80 flex-shrink-0\" />\n                  <span className=\"truncate\">{agent.currentTask}</span>\n                </div>\n              )}\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n};\n",
  },
  "MessageBubble": {
    filename: "MessageBubble.tsx",
    content: "import React, { useState } from 'react';\nimport {\n  User,\n  Sparkles,\n  Copy,\n  Check,\n  RotateCcw,\n  Pencil,\n  FileText,\n  Clock,\n  Cpu,\n  Code,\n  ArrowUpRight,\n} from 'lucide-react';\nimport { cn } from './cn';\nimport type { AgentMessage } from './types';\nimport { StreamingText } from './StreamingText';\nimport { BranchSwitcher } from './BranchSwitcher';\nimport { ReasoningAccordion } from './ReasoningAccordion';\nimport { ToolCallCard } from './ToolCallCard';\nimport { AgentPlanView } from './AgentPlanView';\n\nexport interface MessageBubbleProps {\n  message: AgentMessage;\n  variant?: 'solid' | 'subtle' | 'neutral' | 'bordered';\n  onRetry?: (messageId: string) => void;\n  onEdit?: (messageId: string) => void;\n  onSelectBranch?: (messageId: string, branchIndex: number) => void;\n  onApproveTool?: (toolCallId: string) => void;\n  onRejectTool?: (toolCallId: string) => void;\n  onSelectArtifact?: (artifactId: string) => void;\n  className?: string;\n}\n\nexport const MessageBubble: React.FC<MessageBubbleProps> = ({\n  message,\n  variant = 'solid',\n  onRetry,\n  onEdit,\n  onSelectBranch,\n  onApproveTool,\n  onRejectTool,\n  onSelectArtifact,\n  className,\n}) => {\n  const [copied, setCopied] = useState(false);\n  const isUser = message.role === 'user';\n  const isSystem = message.role === 'system';\n\n  const handleCopy = () => {\n    navigator.clipboard.writeText(message.content);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  if (isSystem) {\n    return (\n      <div className={cn('flex justify-center my-3 px-4', className)}>\n        <div className=\"inline-flex items-center gap-1.5 px-3 py-1 rounded-full bg-secondary/80 border border-border/50 text-[11px] text-muted-foreground\">\n          <span>{message.content}</span>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div\n      className={cn(\n        'group flex gap-3 py-3 px-2 sm:px-4 transition-colors rounded-xl',\n        isUser ? 'flex-row-reverse' : 'flex-row',\n        className\n      )}\n    >\n      {/* Avatar */}\n      <div className=\"flex-shrink-0 mt-0.5\">\n        <div\n          className={cn(\n            'flex h-7 w-7 items-center justify-center rounded-full border text-xs font-medium shadow-xs select-none',\n            isUser\n              ? variant === 'subtle'\n                ? 'bg-primary/15 text-primary border-primary/30'\n                : variant === 'neutral'\n                ? 'bg-secondary text-foreground border-border/70'\n                : variant === 'bordered'\n                ? 'bg-background text-primary border-2 border-primary/60'\n                : 'bg-primary text-primary-foreground border-primary/20'\n              : 'bg-secondary text-foreground border-border/60'\n          )}\n        >\n          {message.avatar ? (\n            <img\n              src={message.avatar}\n              alt={message.name || 'User'}\n              className=\"h-full w-full rounded-full object-cover\"\n            />\n          ) : isUser ? (\n            <User className=\"h-3.5 w-3.5\" />\n          ) : (\n            <Sparkles className=\"h-3.5 w-3.5 text-primary\" />\n          )}\n        </div>\n      </div>\n\n      {/* Main Content Area */}\n      <div\n        className={cn(\n          'flex flex-col max-w-[88%] sm:max-w-[82%] min-w-0',\n          isUser ? 'items-end' : 'items-start'\n        )}\n      >\n        {/* Header (Author, Model Badge, Latency, Token Metrics) */}\n        <div className=\"flex items-center gap-2 mb-1 text-[11px] text-muted-foreground\">\n          <span className=\"font-semibold text-foreground text-xs\">\n            {message.name || (isUser ? 'You' : 'Assistant')}\n          </span>\n\n          {message.model && (\n            <span className=\"hidden sm:inline-flex items-center gap-1 px-1.5 py-0.2 rounded bg-secondary text-[10px] text-muted-foreground border border-border/40 font-mono\">\n              {message.model.name}\n            </span>\n          )}\n\n          {message.latencyMs !== undefined && (\n            <span className=\"hidden md:inline-flex items-center gap-0.5 text-[10px] text-muted-foreground/70 font-mono\">\n              <Clock className=\"h-2.5 w-2.5\" />\n              {(message.latencyMs / 1000).toFixed(1)}s\n            </span>\n          )}\n\n          {message.tokens?.total !== undefined && (\n            <span className=\"hidden md:inline-flex items-center gap-0.5 text-[10px] text-muted-foreground/70 font-mono\">\n              <Cpu className=\"h-2.5 w-2.5\" />\n              {message.tokens.total} toks\n            </span>\n          )}\n        </div>\n\n        {/* Attachment Previews */}\n        {message.attachments && message.attachments.length > 0 && (\n          <div className=\"flex flex-wrap gap-2 mb-2\">\n            {message.attachments.map((att) => (\n              <div\n                key={att.id}\n                className=\"flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-secondary/80 border border-border/60 text-xs font-mono\"\n              >\n                <FileText className=\"h-3 w-3 text-muted-foreground\" />\n                <span className=\"truncate max-w-[140px] text-foreground\">\n                  {att.name}\n                </span>\n                <span className=\"text-[10px] text-muted-foreground\">\n                  {(att.size / 1024).toFixed(0)}KB\n                </span>\n              </div>\n            ))}\n          </div>\n        )}\n\n        {/* Reasoning / CoT Stream Accordion */}\n        {message.thoughts && message.thoughts.length > 0 && (\n          <div className=\"w-full\">\n            {message.thoughts.map((thought) => (\n              <ReasoningAccordion key={thought.id} thought={thought} />\n            ))}\n          </div>\n        )}\n\n        {/* Agent Plan Hierarchy */}\n        {message.plan && (\n          <div className=\"w-full\">\n            <AgentPlanView plan={message.plan} />\n          </div>\n        )}\n\n        {/* Tool Call Cards */}\n        {message.toolCalls && message.toolCalls.length > 0 && (\n          <div className=\"w-full space-y-1 my-1\">\n            {message.toolCalls.map((tc) => (\n              <ToolCallCard\n                key={tc.id}\n                toolCall={tc}\n                onApprove={onApproveTool}\n                onReject={onRejectTool}\n              />\n            ))}\n          </div>\n        )}\n\n        {/* Core Message Bubble Body */}\n        {message.content && (\n          <div\n            className={cn(\n              'rounded-2xl px-4 py-2.5 text-xs transition-shadow',\n              isUser\n                ? variant === 'subtle'\n                  ? 'bg-primary/10 text-foreground border border-primary/25 rounded-tr-sm shadow-xs'\n                  : variant === 'neutral'\n                  ? 'bg-secondary text-foreground border border-border/70 rounded-tr-sm shadow-xs'\n                  : variant === 'bordered'\n                  ? 'bg-background text-foreground border-2 border-primary/60 rounded-tr-sm shadow-xs'\n                  : 'bg-primary text-primary-foreground rounded-tr-sm shadow-xs'\n                : variant === 'subtle'\n                ? 'bg-secondary/40 border border-border/50 rounded-tl-sm text-foreground shadow-xs w-full'\n                : variant === 'bordered'\n                ? 'bg-card border-2 border-border/80 rounded-tl-sm text-foreground shadow-sm w-full'\n                : 'bg-card border border-border/60 rounded-tl-sm text-foreground shadow-xs w-full'\n            )}\n          >\n            {isUser ? (\n              <p className=\"whitespace-pre-wrap leading-relaxed select-text font-sans\">\n                {message.content}\n              </p>\n            ) : (\n              <StreamingText\n                content={message.content}\n                isStreaming={message.status === 'streaming'}\n              />\n            )}\n          </div>\n        )}\n\n        {/* Artifacts Attached Pills */}\n        {message.artifacts && message.artifacts.length > 0 && (\n          <div className=\"flex flex-wrap gap-2 mt-2.5\">\n            {message.artifacts.map((art) => (\n              <button\n                key={art.id}\n                type=\"button\"\n                onClick={() => onSelectArtifact && onSelectArtifact(art.id)}\n                className=\"group/art inline-flex items-center gap-2.5 px-3 py-1.5 rounded-xl bg-card hover:bg-secondary border border-border/80 hover:border-primary/50 text-xs font-mono text-foreground shadow-2xs transition-all select-none text-left\"\n              >\n                <div className=\"flex h-5 w-5 items-center justify-center rounded-md bg-primary/15 text-primary flex-shrink-0\">\n                  <Code className=\"h-3 w-3\" />\n                </div>\n                <span className=\"font-semibold text-foreground truncate max-w-[200px]\">\n                  {art.title}\n                </span>\n                <span className=\"text-[10px] uppercase font-mono px-1.5 py-0.5 rounded bg-primary text-primary-foreground font-bold tracking-wider shadow-2xs\">\n                  {art.type}\n                </span>\n                <ArrowUpRight className=\"h-3 w-3 text-muted-foreground group-hover/art:text-foreground transition-colors ml-0.5\" />\n              </button>\n            ))}\n          </div>\n        )}\n\n        {/* Action Controls Toolbar (Copy, Retry, Branching) */}\n        <div\n          className={cn(\n            'flex items-center gap-1.5 mt-1.5 opacity-0 group-hover:opacity-100 transition-opacity',\n            isUser ? 'self-end' : 'self-start'\n          )}\n        >\n          {message.branches && message.branches.length > 1 && (\n            <BranchSwitcher\n              currentIndex={message.selectedBranchIndex || 0}\n              totalBranches={message.branches.length}\n              onSelectBranch={(idx) =>\n                onSelectBranch && onSelectBranch(message.id, idx)\n              }\n            />\n          )}\n\n          <button\n            type=\"button\"\n            onClick={handleCopy}\n            className=\"p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n            title=\"Copy message\"\n          >\n            {copied ? (\n              <Check className=\"h-3 w-3 text-emerald-500\" />\n            ) : (\n              <Copy className=\"h-3 w-3\" />\n            )}\n          </button>\n\n          {isUser && onEdit && (\n            <button\n              type=\"button\"\n              onClick={() => onEdit(message.id)}\n              className=\"p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n              title=\"Edit prompt\"\n            >\n              <Pencil className=\"h-3 w-3\" />\n            </button>\n          )}\n\n          {!isUser && onRetry && (\n            <button\n              type=\"button\"\n              onClick={() => onRetry(message.id)}\n              className=\"p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n              title=\"Regenerate response\"\n            >\n              <RotateCcw className=\"h-3 w-3\" />\n            </button>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n};\n",
  },
  "StreamingText": {
    filename: "StreamingText.tsx",
    content: "import React from 'react';\nimport { cn } from './cn';\n\nexport interface StreamingTextProps {\n  content: string;\n  isStreaming?: boolean;\n  className?: string;\n}\n\nexport const StreamingText: React.FC<StreamingTextProps> = ({\n  content,\n  isStreaming = false,\n  className,\n}) => {\n  // Simple, robust markdown line parser for zero-dependency streaming rendering\n  const renderFormattedText = (text: string) => {\n    const lines = text.split('\\n');\n    let inCodeBlock = false;\n    let codeBlockContent: string[] = [];\n    let codeBlockLang = '';\n\n    const elements: React.ReactNode[] = [];\n\n    lines.forEach((line, idx) => {\n      // Code Block Start/End\n      if (line.startsWith('```')) {\n        if (inCodeBlock) {\n          elements.push(\n            <div\n              key={`code-${idx}`}\n              className=\"my-3 rounded-lg overflow-hidden border border-border/60 bg-neutral-950 text-neutral-100 font-mono text-xs shadow-sm\"\n            >\n              {codeBlockLang && (\n                <div className=\"flex items-center justify-between px-3 py-1.5 bg-neutral-900 border-b border-neutral-800 text-[10px] text-neutral-400 font-sans uppercase\">\n                  <span>{codeBlockLang}</span>\n                </div>\n              )}\n              <pre className=\"p-3 overflow-x-auto\">\n                <code>{codeBlockContent.join('\\n')}</code>\n              </pre>\n            </div>\n          );\n          codeBlockContent = [];\n          inCodeBlock = false;\n          codeBlockLang = '';\n        } else {\n          inCodeBlock = true;\n          codeBlockLang = line.replace('```', '').trim();\n        }\n        return;\n      }\n\n      if (inCodeBlock) {\n        codeBlockContent.push(line);\n        return;\n      }\n\n      // Headings\n      if (line.startsWith('### ')) {\n        elements.push(\n          <h3 key={idx} className=\"text-sm font-semibold text-foreground mt-3 mb-1\">\n            {line.replace('### ', '')}\n          </h3>\n        );\n        return;\n      }\n      if (line.startsWith('## ')) {\n        elements.push(\n          <h2 key={idx} className=\"text-base font-bold text-foreground mt-4 mb-1.5\">\n            {line.replace('## ', '')}\n          </h2>\n        );\n        return;\n      }\n      if (line.startsWith('# ')) {\n        elements.push(\n          <h1 key={idx} className=\"text-lg font-bold text-foreground mt-4 mb-2\">\n            {line.replace('# ', '')}\n          </h1>\n        );\n        return;\n      }\n\n      // Blockquotes\n      if (line.startsWith('> ')) {\n        elements.push(\n          <blockquote\n            key={idx}\n            className=\"border-l-2 border-primary/40 pl-3 italic text-muted-foreground my-2 text-xs\"\n          >\n            {line.replace('> ', '')}\n          </blockquote>\n        );\n        return;\n      }\n\n      // Bullet lists\n      if (line.startsWith('- ') || line.startsWith('* ')) {\n        elements.push(\n          <li key={idx} className=\"ml-4 list-disc text-foreground/90 my-0.5 text-xs\">\n            {renderInlineSpans(line.substring(2))}\n          </li>\n        );\n        return;\n      }\n\n      // Numbered lists\n      const numMatch = line.match(/^(\\d+)\\.\\s(.*)/);\n      if (numMatch) {\n        elements.push(\n          <li key={idx} className=\"ml-4 list-decimal text-foreground/90 my-0.5 text-xs\">\n            {renderInlineSpans(numMatch[2])}\n          </li>\n        );\n        return;\n      }\n\n      // Normal paragraph\n      if (line.trim() === '') {\n        elements.push(<div key={idx} className=\"h-2\" />);\n      } else {\n        elements.push(\n          <p key={idx} className=\"my-1 text-xs leading-relaxed text-foreground/90\">\n            {renderInlineSpans(line)}\n          </p>\n        );\n      }\n    });\n\n    // If still in codeblock while streaming\n    if (inCodeBlock && codeBlockContent.length > 0) {\n      elements.push(\n        <div\n          key=\"code-incomplete\"\n          className=\"my-3 rounded-lg overflow-hidden border border-border/60 bg-neutral-950 text-neutral-100 font-mono text-xs\"\n        >\n          <pre className=\"p-3 overflow-x-auto\">\n            <code>{codeBlockContent.join('\\n')}</code>\n          </pre>\n        </div>\n      );\n    }\n\n    return elements;\n  };\n\n  // Inline formatting helper (bold, code, italic)\n  const renderInlineSpans = (text: string): React.ReactNode => {\n    // Handle inline code `code`\n    const parts = text.split(/(`[^`]+`|\\*\\*[^*]+\\*\\*)/g);\n    return parts.map((part, i) => {\n      if (part.startsWith('`') && part.endsWith('`')) {\n        return (\n          <code\n            key={i}\n            className=\"px-1.5 py-0.5 rounded bg-muted font-mono text-[11px] text-foreground border border-border/50\"\n          >\n            {part.slice(1, -1)}\n          </code>\n        );\n      }\n      if (part.startsWith('**') && part.endsWith('**')) {\n        return (\n          <strong key={i} className=\"font-semibold text-foreground\">\n            {part.slice(2, -2)}\n          </strong>\n        );\n      }\n      return part;\n    });\n  };\n\n  return (\n    <div className={cn('text-xs leading-relaxed font-sans select-text', className)}>\n      {renderFormattedText(content)}\n      {isStreaming && (\n        <span className=\"inline-block h-3.5 w-1.5 ml-0.5 bg-primary animate-stream-cursor align-middle rounded-sm\" />\n      )}\n    </div>\n  );\n};\n",
  },
  "BranchSwitcher": {
    filename: "BranchSwitcher.tsx",
    content: "import React from 'react';\nimport { ChevronLeft, ChevronRight, GitFork } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface BranchSwitcherProps {\n  currentIndex: number;\n  totalBranches: number;\n  onSelectBranch: (index: number) => void;\n  className?: string;\n}\n\nexport const BranchSwitcher: React.FC<BranchSwitcherProps> = ({\n  currentIndex,\n  totalBranches,\n  onSelectBranch,\n  className,\n}) => {\n  if (totalBranches <= 1) return null;\n\n  return (\n    <div\n      className={cn(\n        'inline-flex items-center gap-1 px-1.5 py-0.5 rounded-full bg-secondary/80 border border-border/50 text-[10px] text-muted-foreground font-mono select-none',\n        className\n      )}\n    >\n      <GitFork className=\"h-2.5 w-2.5 text-muted-foreground/80\" />\n      <button\n        type=\"button\"\n        disabled={currentIndex <= 0}\n        onClick={() => onSelectBranch(currentIndex - 1)}\n        className=\"p-0.5 rounded hover:bg-background/80 hover:text-foreground disabled:opacity-30 disabled:hover:bg-transparent transition-colors\"\n        aria-label=\"Previous branch\"\n      >\n        <ChevronLeft className=\"h-3 w-3\" />\n      </button>\n\n      <span>\n        {currentIndex + 1}/{totalBranches}\n      </span>\n\n      <button\n        type=\"button\"\n        disabled={currentIndex >= totalBranches - 1}\n        onClick={() => onSelectBranch(currentIndex + 1)}\n        className=\"p-0.5 rounded hover:bg-background/80 hover:text-foreground disabled:opacity-30 disabled:hover:bg-transparent transition-colors\"\n        aria-label=\"Next branch\"\n      >\n        <ChevronRight className=\"h-3 w-3\" />\n      </button>\n    </div>\n  );\n};\n",
  },
  "ChatContainer": {
    filename: "ChatContainer.tsx",
    content: "import React, { useRef, useState, useEffect, useCallback } from 'react';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport { ArrowDown } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface ChatContainerProps {\n  children: React.ReactNode;\n  isStreaming?: boolean;\n  className?: string;\n  autoScrollThreshold?: number;\n}\n\nexport const ChatContainer: React.FC<ChatContainerProps> = ({\n  children,\n  isStreaming = false,\n  className,\n  autoScrollThreshold = 100,\n}) => {\n  const containerRef = useRef<HTMLDivElement>(null);\n  const bottomAnchorRef = useRef<HTMLDivElement>(null);\n  const [showScrollBottom, setShowScrollBottom] = useState(false);\n  const [userScrolledUp, setUserScrolledUp] = useState(false);\n\n  const scrollToBottom = useCallback((smooth = true) => {\n    bottomAnchorRef.current?.scrollIntoView({\n      behavior: smooth ? 'smooth' : 'auto',\n      block: 'end',\n    });\n    setUserScrolledUp(false);\n    setShowScrollBottom(false);\n  }, []);\n\n  // Handle scroll events to detect if user scrolled away from bottom\n  const handleScroll = () => {\n    if (!containerRef.current) return;\n    const { scrollTop, scrollHeight, clientHeight } = containerRef.current;\n    const distanceFromBottom = scrollHeight - scrollTop - clientHeight;\n\n    if (distanceFromBottom > autoScrollThreshold) {\n      setUserScrolledUp(true);\n      setShowScrollBottom(true);\n    } else {\n      setUserScrolledUp(false);\n      setShowScrollBottom(false);\n    }\n  };\n\n  // Auto-scroll when children change or when streaming if user hasn't scrolled up\n  useEffect(() => {\n    if (!userScrolledUp) {\n      scrollToBottom(false);\n    }\n  }, [children, isStreaming, userScrolledUp, scrollToBottom]);\n\n  return (\n    <div className=\"relative flex-1 h-full w-full overflow-hidden flex flex-col\">\n      <div\n        ref={containerRef}\n        onScroll={handleScroll}\n        className={cn(\n          'flex-1 overflow-y-auto overflow-x-hidden p-3 sm:p-6 space-y-4 scroll-smooth',\n          className\n        )}\n      >\n        {children}\n        <div ref={bottomAnchorRef} className=\"h-4 w-full flex-shrink-0\" />\n      </div>\n\n      {/* Floating Jump to Bottom Pill */}\n      <AnimatePresence>\n        {showScrollBottom && (\n          <motion.div\n            initial={{ opacity: 0, y: 10, scale: 0.9 }}\n            animate={{ opacity: 1, y: 0, scale: 1 }}\n            exit={{ opacity: 0, y: 10, scale: 0.9 }}\n            className=\"absolute bottom-4 right-6 z-10\"\n          >\n            <button\n              type=\"button\"\n              onClick={() => scrollToBottom(true)}\n              className=\"flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-background/90 text-foreground border border-border/80 shadow-lg backdrop-blur-md text-xs font-medium hover:bg-secondary transition-all\"\n            >\n              <ArrowDown className=\"h-3.5 w-3.5\" />\n              <span>Scroll to bottom</span>\n            </button>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n};\n",
  },
  "PromptInput": {
    filename: "PromptInput.tsx",
    content: "import React, { useState, useRef, useEffect } from 'react';\nimport {\n  ArrowUp,\n  Square,\n  Paperclip,\n} from 'lucide-react';\nimport { cn } from './cn';\nimport type { ModelInfo, FileAttachment } from './types';\nimport { ModelSelector } from './ModelSelector';\nimport { ContextTray, type ContextItem } from './ContextTray';\nimport { SlashCommandMenu, type SlashCommand } from './SlashCommandMenu';\n\nexport interface PromptInputProps {\n  value: string;\n  onChange: (value: string) => void;\n  onSubmit: (content: string, attachments?: FileAttachment[]) => void;\n  onStop?: () => void;\n  isStreaming?: boolean;\n  placeholder?: string;\n  models?: ModelInfo[];\n  selectedModel?: ModelInfo;\n  onSelectModel?: (model: ModelInfo) => void;\n  contextItems?: ContextItem[];\n  onRemoveContextItem?: (id: string) => void;\n  attachments?: FileAttachment[];\n  onUploadClick?: () => void;\n  className?: string;\n}\n\nexport const PromptInput: React.FC<PromptInputProps> = ({\n  value,\n  onChange,\n  onSubmit,\n  onStop,\n  isStreaming = false,\n  placeholder = 'Ask a question or type / for commands...',\n  models,\n  selectedModel,\n  onSelectModel,\n  contextItems = [],\n  onRemoveContextItem,\n  attachments = [],\n  onUploadClick,\n  className,\n}) => {\n  const textareaRef = useRef<HTMLTextAreaElement>(null);\n  const [showSlashMenu, setShowSlashMenu] = useState(false);\n  const [slashFilter, setSlashFilter] = useState('');\n\n  // Auto-resize textarea height\n  useEffect(() => {\n    if (textareaRef.current) {\n      textareaRef.current.style.height = 'auto';\n      textareaRef.current.style.height = `${Math.min(\n        textareaRef.current.scrollHeight,\n        220\n      )}px`;\n    }\n  }, [value]);\n\n  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {\n    if (e.key === 'Enter' && !e.shiftKey) {\n      e.preventDefault();\n      if (!isStreaming && (value.trim() || attachments.length > 0)) {\n        onSubmit(value, attachments);\n      }\n    } else if (e.key === 'Escape') {\n      setShowSlashMenu(false);\n    }\n  };\n\n  const handleInputChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {\n    const val = e.target.value;\n    onChange(val);\n\n    if (val.startsWith('/')) {\n      setShowSlashMenu(true);\n      setSlashFilter(val.slice(1));\n    } else {\n      setShowSlashMenu(false);\n    }\n  };\n\n  const handleSelectSlashCommand = (cmd: SlashCommand) => {\n    onChange(`${cmd.name} `);\n    setShowSlashMenu(false);\n    textareaRef.current?.focus();\n  };\n\n  // Rough token estimation (~4 chars per token)\n  const estimatedTokens = Math.ceil(value.length / 4);\n\n  return (\n    <div\n      className={cn(\n        'relative rounded-2xl border border-border/80 bg-card/90 backdrop-blur-md shadow-lg transition-all duration-200 focus-within:border-primary/60 focus-within:ring-1 focus-within:ring-primary/30',\n        className\n      )}\n    >\n      {/* Pinned Context Tray */}\n      {contextItems.length > 0 && onRemoveContextItem && (\n        <ContextTray\n          items={contextItems}\n          onRemoveItem={onRemoveContextItem}\n        />\n      )}\n\n      {/* Slash Command Autocomplete Popover */}\n      <SlashCommandMenu\n        isOpen={showSlashMenu}\n        filterText={slashFilter}\n        onSelectCommand={handleSelectSlashCommand}\n        onClose={() => setShowSlashMenu(false)}\n      />\n\n      {/* Textarea Area */}\n      <div className=\"px-4 pt-3.5 pb-2\">\n        <textarea\n          ref={textareaRef}\n          value={value}\n          onChange={handleInputChange}\n          onKeyDown={handleKeyDown}\n          placeholder={placeholder}\n          rows={1}\n          className=\"w-full resize-none bg-transparent text-sm text-foreground placeholder:text-muted-foreground/60 focus:outline-hidden leading-relaxed max-h-56\"\n        />\n      </div>\n\n      {/* Bottom Action Controls Bar */}\n      <div className=\"flex items-center justify-between px-3 pb-3 pt-1 text-xs\">\n        <div className=\"flex items-center gap-1.5 min-w-0\">\n          {/* Model Selector */}\n          {models && selectedModel && onSelectModel && (\n            <ModelSelector\n              models={models}\n              selectedModel={selectedModel}\n              onSelectModel={onSelectModel}\n            />\n          )}\n\n          {/* Attachment Upload Button */}\n          {onUploadClick && (\n            <button\n              type=\"button\"\n              onClick={onUploadClick}\n              className=\"inline-flex items-center gap-1 p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n              title=\"Attach files or images\"\n            >\n              <Paperclip className=\"h-3.5 w-3.5\" />\n              {attachments.length > 0 && (\n                <span className=\"text-[10px] font-mono font-medium px-1 rounded bg-secondary\">\n                  {attachments.length}\n                </span>\n              )}\n            </button>\n          )}\n\n          {/* Token Counter */}\n          {value.length > 0 && (\n            <span className=\"hidden sm:inline-block text-[10px] font-mono text-muted-foreground/70 ml-1\">\n              ~{estimatedTokens} tokens\n            </span>\n          )}\n        </div>\n\n        {/* Submit or Stop Button */}\n        <div className=\"flex items-center gap-2\">\n          {isStreaming ? (\n            <button\n              type=\"button\"\n              onClick={onStop}\n              className=\"flex h-8 w-8 items-center justify-center rounded-full bg-rose-500 hover:bg-rose-600 text-white shadow-sm transition-all\"\n              title=\"Stop generation\"\n            >\n              <Square className=\"h-3.5 w-3.5 fill-current\" />\n            </button>\n          ) : (\n            <button\n              type=\"button\"\n              disabled={!value.trim() && attachments.length === 0}\n              onClick={() => onSubmit(value, attachments)}\n              className=\"flex h-8 w-8 items-center justify-center rounded-full bg-primary text-primary-foreground hover:opacity-90 disabled:opacity-30 disabled:hover:opacity-30 shadow-sm transition-all\"\n              title=\"Send message (Enter)\"\n            >\n              <ArrowUp className=\"h-4 w-4\" />\n            </button>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n};\n",
  },
  "DragAndDropUploader": {
    filename: "DragAndDropUploader.tsx",
    content: "import React, { useState, useRef } from 'react';\nimport { UploadCloud, FileText, Image as ImageIcon, FileCode, X, CheckCircle2, Loader2 } from 'lucide-react';\nimport { cn } from './cn';\nimport type { FileAttachment } from './types';\n\nexport interface DragAndDropUploaderProps {\n  attachments: FileAttachment[];\n  onUploadFiles: (files: File[]) => void;\n  onRemoveAttachment: (id: string) => void;\n  maxFiles?: number;\n  accept?: string;\n  className?: string;\n}\n\nexport const DragAndDropUploader: React.FC<DragAndDropUploaderProps> = ({\n  attachments,\n  onUploadFiles,\n  onRemoveAttachment,\n  maxFiles = 5,\n  accept = 'image/*,.pdf,.txt,.csv,.json,.ts,.js,.py,.html,.css',\n  className,\n}) => {\n  const [isDragging, setIsDragging] = useState(false);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  const handleDragOver = (e: React.DragEvent) => {\n    e.preventDefault();\n    e.stopPropagation();\n    setIsDragging(true);\n  };\n\n  const handleDragLeave = (e: React.DragEvent) => {\n    e.preventDefault();\n    e.stopPropagation();\n    setIsDragging(false);\n  };\n\n  const handleDrop = (e: React.DragEvent) => {\n    e.preventDefault();\n    e.stopPropagation();\n    setIsDragging(false);\n    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {\n      const droppedFiles = Array.from(e.dataTransfer.files).slice(0, maxFiles);\n      onUploadFiles(droppedFiles);\n    }\n  };\n\n  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {\n    if (e.target.files && e.target.files.length > 0) {\n      const selectedFiles = Array.from(e.target.files).slice(0, maxFiles);\n      onUploadFiles(selectedFiles);\n    }\n  };\n\n  const getFileIcon = (type: string, name: string) => {\n    if (type.startsWith('image/')) return <ImageIcon className=\"h-4 w-4 text-primary\" />;\n    if (name.endsWith('.ts') || name.endsWith('.js') || name.endsWith('.py') || name.endsWith('.json')) {\n      return <FileCode className=\"h-4 w-4 text-blue-500\" />;\n    }\n    return <FileText className=\"h-4 w-4 text-emerald-500\" />;\n  };\n\n  return (\n    <div className={cn('space-y-2', className)}>\n      {/* Hidden File Input */}\n      <input\n        ref={fileInputRef}\n        type=\"file\"\n        multiple\n        accept={accept}\n        onChange={handleFileChange}\n        className=\"hidden\"\n      />\n\n      {/* Drop Zone Area */}\n      <div\n        onDragOver={handleDragOver}\n        onDragLeave={handleDragLeave}\n        onDrop={handleDrop}\n        onClick={() => fileInputRef.current?.click()}\n        className={cn(\n          'border-2 border-dashed rounded-xl p-4 text-center cursor-pointer transition-all duration-200 backdrop-blur-sm',\n          isDragging\n            ? 'border-primary bg-primary/10 scale-[0.99]'\n            : 'border-border/60 hover:border-primary/50 hover:bg-secondary/40 bg-secondary/20'\n        )}\n      >\n        <div className=\"flex flex-col items-center justify-center gap-1.5 text-muted-foreground\">\n          <div className=\"flex h-9 w-9 items-center justify-center rounded-full bg-background border border-border/60 shadow-xs\">\n            <UploadCloud className=\"h-4 w-4 text-foreground/70\" />\n          </div>\n          <p className=\"text-xs font-medium text-foreground\">\n            Click to upload or drag & drop files\n          </p>\n          <p className=\"text-[10px] text-muted-foreground font-mono\">\n            Images, PDFs, CSVs, Code files (max {maxFiles} files)\n          </p>\n        </div>\n      </div>\n\n      {/* Attachments List */}\n      {attachments.length > 0 && (\n        <div className=\"grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2\">\n          {attachments.map((att) => (\n            <div\n              key={att.id}\n              className=\"relative flex items-center gap-2.5 p-2 rounded-lg bg-card border border-border/60 shadow-xs group\"\n            >\n              {/* Thumbnail or File Icon */}\n              <div className=\"flex h-8 w-8 items-center justify-center rounded-md bg-secondary/80 flex-shrink-0 overflow-hidden\">\n                {att.previewUrl ? (\n                  <img\n                    src={att.previewUrl}\n                    alt={att.name}\n                    className=\"h-full w-full object-cover\"\n                  />\n                ) : (\n                  getFileIcon(att.type, att.name)\n                )}\n              </div>\n\n              {/* Details */}\n              <div className=\"min-w-0 flex-1\">\n                <p className=\"text-xs font-medium text-foreground truncate\">\n                  {att.name}\n                </p>\n                <div className=\"flex items-center gap-1 text-[10px] text-muted-foreground font-mono\">\n                  <span>{(att.size / 1024).toFixed(0)}KB</span>\n                  {att.status === 'uploading' && (\n                    <span className=\"inline-flex items-center gap-0.5 text-primary\">\n                      <Loader2 className=\"h-2.5 w-2.5 animate-spin\" />\n                      {att.progress !== undefined ? `${att.progress}%` : ''}\n                    </span>\n                  )}\n                  {att.status === 'ready' && (\n                    <CheckCircle2 className=\"h-2.5 w-2.5 text-emerald-500\" />\n                  )}\n                </div>\n              </div>\n\n              {/* Remove button */}\n              <button\n                type=\"button\"\n                onClick={(e) => {\n                  e.stopPropagation();\n                  onRemoveAttachment(att.id);\n                }}\n                className=\"p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n                title=\"Remove attachment\"\n              >\n                <X className=\"h-3.5 w-3.5\" />\n              </button>\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n};\n",
  },
  "ContextTray": {
    filename: "ContextTray.tsx",
    content: "import React from 'react';\nimport { X, FileCode, Brain, Database, Wrench, Sparkles } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface ContextItem {\n  id: string;\n  label: string;\n  type: 'file' | 'memory' | 'database' | 'tool' | 'custom';\n  meta?: string;\n}\n\nexport interface ContextTrayProps {\n  items: ContextItem[];\n  onRemoveItem: (id: string) => void;\n  onClearAll?: () => void;\n  className?: string;\n}\n\nconst getContextIcon = (type: ContextItem['type']) => {\n  switch (type) {\n    case 'file':\n      return <FileCode className=\"h-3 w-3 text-blue-500\" />;\n    case 'memory':\n      return <Brain className=\"h-3 w-3 text-primary\" />;\n    case 'database':\n      return <Database className=\"h-3 w-3 text-emerald-500\" />;\n    case 'tool':\n      return <Wrench className=\"h-3 w-3 text-amber-500\" />;\n    default:\n      return <Sparkles className=\"h-3 w-3 text-primary\" />;\n  }\n};\n\nexport const ContextTray: React.FC<ContextTrayProps> = ({\n  items,\n  onRemoveItem,\n  onClearAll,\n  className,\n}) => {\n  if (items.length === 0) return null;\n\n  return (\n    <div\n      className={cn(\n        'flex items-center gap-1.5 px-3 py-1.5 border-b border-border/40 bg-secondary/30 overflow-x-auto text-xs rounded-t-2xl',\n        className\n      )}\n    >\n      <span className=\"text-[10px] uppercase font-mono tracking-wider text-muted-foreground flex-shrink-0\">\n        Context ({items.length}):\n      </span>\n\n      <div className=\"flex items-center gap-1.5 flex-1 min-w-0\">\n        {items.map((item) => (\n          <div\n            key={item.id}\n            className=\"inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-background/90 border border-border/60 text-[11px] font-mono text-foreground flex-shrink-0 group shadow-2xs\"\n          >\n            {getContextIcon(item.type)}\n            <span className=\"truncate max-w-[120px]\">{item.label}</span>\n            {item.meta && (\n              <span className=\"text-[10px] text-muted-foreground\">\n                ({item.meta})\n              </span>\n            )}\n            <button\n              type=\"button\"\n              onClick={() => onRemoveItem(item.id)}\n              className=\"p-0.5 rounded-full hover:bg-secondary text-muted-foreground hover:text-foreground transition-colors ml-0.5\"\n            >\n              <X className=\"h-2.5 w-2.5\" />\n            </button>\n          </div>\n        ))}\n      </div>\n\n      {onClearAll && items.length > 2 && (\n        <button\n          type=\"button\"\n          onClick={onClearAll}\n          className=\"text-[10px] text-muted-foreground hover:text-foreground flex-shrink-0 ml-1 hover:underline\"\n        >\n          Clear all\n        </button>\n      )}\n    </div>\n  );\n};\n",
  },
  "SlashCommandMenu": {
    filename: "SlashCommandMenu.tsx",
    content: "import React, { useState, useEffect, useRef } from 'react';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport { Sparkles, Terminal, Search, FileText, CheckSquare, Zap } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface SlashCommand {\n  id: string;\n  name: string;\n  description: string;\n  icon?: React.ReactNode;\n}\n\nexport interface SlashCommandMenuProps {\n  isOpen: boolean;\n  filterText: string;\n  commands?: SlashCommand[];\n  onSelectCommand: (command: SlashCommand) => void;\n  onClose: () => void;\n  placement?: 'bottom-full' | 'top-full' | 'inline';\n  className?: string;\n}\n\nconst defaultCommands: SlashCommand[] = [\n  { id: 'plan', name: '/plan', description: 'Generate a step-by-step implementation plan', icon: <CheckSquare className=\"h-3.5 w-3.5\" /> },\n  { id: 'search', name: '/search', description: 'Search the web or knowledge base', icon: <Search className=\"h-3.5 w-3.5\" /> },\n  { id: 'terminal', name: '/exec', description: 'Run a shell command or script', icon: <Terminal className=\"h-3.5 w-3.5\" /> },\n  { id: 'file', name: '/file', description: 'Create or edit an artifact file', icon: <FileText className=\"h-3.5 w-3.5\" /> },\n  { id: 'fast', name: '/fast', description: 'Fast reasoning mode with concise response', icon: <Zap className=\"h-3.5 w-3.5\" /> },\n];\n\nexport const SlashCommandMenu: React.FC<SlashCommandMenuProps> = ({\n  isOpen,\n  filterText,\n  commands = defaultCommands,\n  onSelectCommand,\n  onClose,\n  placement = 'bottom-full',\n  className,\n}) => {\n  const [selectedIndex, setSelectedIndex] = useState(0);\n  const menuRef = useRef<HTMLDivElement>(null);\n\n  const filteredCommands = commands.filter(\n    (c) =>\n      c.name.toLowerCase().includes(filterText.toLowerCase()) ||\n      c.description.toLowerCase().includes(filterText.toLowerCase())\n  );\n\n  useEffect(() => {\n    setSelectedIndex(0);\n  }, [filterText]);\n\n  // Click-outside listener without hijacking browser viewport\n  useEffect(() => {\n    if (!isOpen || placement === 'inline') return;\n\n    const handlePointerDown = (e: MouseEvent | TouchEvent) => {\n      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {\n        onClose();\n      }\n    };\n\n    document.addEventListener('mousedown', handlePointerDown);\n    document.addEventListener('touchstart', handlePointerDown);\n    return () => {\n      document.removeEventListener('mousedown', handlePointerDown);\n      document.removeEventListener('touchstart', handlePointerDown);\n    };\n  }, [isOpen, placement, onClose]);\n\n  if (!isOpen || filteredCommands.length === 0) return null;\n\n  const placementClasses = {\n    'bottom-full': 'absolute left-3 bottom-full mb-2 w-72 shadow-xl z-50',\n    'top-full': 'absolute left-3 top-full mt-2 w-72 shadow-xl z-50',\n    'inline': 'relative w-full shadow-sm',\n  }[placement];\n\n  return (\n    <AnimatePresence>\n      <motion.div\n        ref={menuRef}\n        initial={{ opacity: 0, y: placement === 'bottom-full' ? 8 : -8, scale: 0.97 }}\n        animate={{ opacity: 1, y: 0, scale: 1 }}\n        exit={{ opacity: 0, y: placement === 'bottom-full' ? 8 : -8, scale: 0.97 }}\n        transition={{ duration: 0.15 }}\n        className={cn(\n          'rounded-xl border border-border/80 bg-popover/95 backdrop-blur-md p-1.5 space-y-0.5',\n          placementClasses,\n          className\n        )}\n      >\n        <div className=\"px-2 py-1 text-[10px] font-mono uppercase tracking-wider text-muted-foreground border-b border-border/40\">\n          Slash Commands\n        </div>\n\n        <div className=\"max-h-56 overflow-y-auto space-y-0.5\">\n          {filteredCommands.map((cmd, idx) => {\n            const isSelected = idx === selectedIndex;\n            return (\n              <button\n                key={cmd.id}\n                type=\"button\"\n                onClick={() => onSelectCommand(cmd)}\n                className={cn(\n                  'w-full flex items-center gap-2.5 p-2 rounded-lg text-xs text-left transition-colors',\n                  isSelected\n                    ? 'bg-primary text-primary-foreground font-semibold shadow-2xs'\n                    : 'text-foreground hover:bg-secondary'\n                )}\n              >\n                <div\n                  className={cn(\n                    'flex h-5 w-5 items-center justify-center rounded-md text-xs',\n                    isSelected\n                      ? 'bg-primary-foreground/20 text-primary-foreground'\n                      : 'bg-secondary text-muted-foreground'\n                  )}\n                >\n                  {cmd.icon || <Sparkles className=\"h-3 w-3\" />}\n                </div>\n                <div className=\"min-w-0 flex-1\">\n                  <div\n                    className={cn(\n                      'font-mono font-semibold',\n                      isSelected ? 'text-primary-foreground' : 'text-foreground'\n                    )}\n                  >\n                    {cmd.name}\n                  </div>\n                  <div\n                    className={cn(\n                      'text-[10px] truncate',\n                      isSelected ? 'text-primary-foreground/80' : 'text-muted-foreground'\n                    )}\n                  >\n                    {cmd.description}\n                  </div>\n                </div>\n              </button>\n            );\n          })}\n        </div>\n      </motion.div>\n    </AnimatePresence>\n  );\n};\n",
  },
  "ModelSelector": {
    filename: "ModelSelector.tsx",
    content: "import React, { useState, useEffect, useRef } from 'react';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport { ChevronDown, Sparkles, Zap, Brain, Check } from 'lucide-react';\nimport { cn } from './cn';\nimport type { ModelInfo } from './types';\n\nexport interface ModelSelectorProps {\n  models: ModelInfo[];\n  selectedModel: ModelInfo;\n  onSelectModel: (model: ModelInfo) => void;\n  placement?: 'bottom-full' | 'top-full';\n  className?: string;\n}\n\nexport const ModelSelector: React.FC<ModelSelectorProps> = ({\n  models,\n  selectedModel,\n  onSelectModel,\n  placement = 'bottom-full',\n  className,\n}) => {\n  const [isOpen, setIsOpen] = useState(false);\n  const containerRef = useRef<HTMLDivElement>(null);\n\n  // Click outside handler without blocking document interaction\n  useEffect(() => {\n    if (!isOpen) return;\n\n    const handlePointerDown = (e: MouseEvent | TouchEvent) => {\n      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {\n        setIsOpen(false);\n      }\n    };\n\n    document.addEventListener('mousedown', handlePointerDown);\n    document.addEventListener('touchstart', handlePointerDown);\n    return () => {\n      document.removeEventListener('mousedown', handlePointerDown);\n      document.removeEventListener('touchstart', handlePointerDown);\n    };\n  }, [isOpen]);\n\n  return (\n    <div ref={containerRef} className={cn('relative inline-block text-left', className)}>\n      <button\n        type=\"button\"\n        onClick={() => setIsOpen(!isOpen)}\n        className=\"inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-xs font-medium bg-secondary/80 hover:bg-secondary border border-border/60 text-foreground transition-all shadow-2xs\"\n      >\n        <Sparkles className=\"h-3 w-3 text-primary\" />\n        <span className=\"truncate max-w-[120px]\">{selectedModel.name}</span>\n        <ChevronDown className=\"h-3 w-3 text-muted-foreground ml-0.5\" />\n      </button>\n\n      <AnimatePresence>\n        {isOpen && (\n          <motion.div\n            initial={{ opacity: 0, y: placement === 'bottom-full' ? 6 : -6, scale: 0.96 }}\n            animate={{ opacity: 1, y: 0, scale: 1 }}\n            exit={{ opacity: 0, y: placement === 'bottom-full' ? 6 : -6, scale: 0.96 }}\n            transition={{ duration: 0.15 }}\n            className={cn(\n              'absolute left-0 w-64 rounded-xl border border-border/80 bg-popover/95 backdrop-blur-md shadow-xl z-50 p-1.5 space-y-1',\n              placement === 'bottom-full' ? 'bottom-full mb-2' : 'top-full mt-2'\n            )}\n          >\n            <div className=\"px-2 py-1 text-[10px] font-mono uppercase tracking-wider text-muted-foreground border-b border-border/40\">\n              Select Model\n            </div>\n\n            <div className=\"max-h-60 overflow-y-auto space-y-0.5\">\n              {models.map((m) => {\n                const isSelected = m.id === selectedModel.id;\n                return (\n                  <button\n                    key={m.id}\n                    type=\"button\"\n                    onClick={() => {\n                      onSelectModel(m);\n                      setIsOpen(false);\n                    }}\n                    className={cn(\n                      'w-full flex items-center justify-between p-2 rounded-lg text-xs text-left transition-colors',\n                      isSelected\n                        ? 'bg-primary text-primary-foreground font-semibold shadow-2xs'\n                        : 'text-foreground hover:bg-secondary'\n                    )}\n                  >\n                    <div className=\"min-w-0 flex-1\">\n                      <div className=\"flex items-center gap-1.5\">\n                        <span className=\"font-semibold\">{m.name}</span>\n                        {m.speed === 'fast' && (\n                          <Zap className={cn(\"h-2.5 w-2.5\", isSelected ? \"text-primary-foreground/90\" : \"text-amber-500\")} />\n                        )}\n                        {m.reasoningEffort === 'high' && (\n                          <Brain className={cn(\"h-2.5 w-2.5\", isSelected ? \"text-primary-foreground/90\" : \"text-primary\")} />\n                        )}\n                      </div>\n                      {m.description && (\n                        <p className={cn(\"text-[10px] truncate mt-0.5\", isSelected ? \"text-primary-foreground/80\" : \"text-muted-foreground\")}>\n                          {m.description}\n                        </p>\n                      )}\n                    </div>\n\n                    {isSelected && (\n                      <Check className=\"h-3.5 w-3.5 text-primary-foreground ml-2 flex-shrink-0\" />\n                    )}\n                  </button>\n                );\n              })}\n            </div>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n};\n",
  },
  "ActionConfirmationModal": {
    filename: "ActionConfirmationModal.tsx",
    content: "import React from 'react';\nimport { motion, AnimatePresence } from 'framer-motion';\nimport { ShieldAlert, Terminal, AlertTriangle, Check, X } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface ActionConfirmationModalProps {\n  isOpen: boolean;\n  title: string;\n  description?: string;\n  actionType: 'command' | 'file_write' | 'api_call' | 'db_mutation' | string;\n  payload: string | Record<string, unknown>;\n  severity?: 'low' | 'medium' | 'critical';\n  onApprove: () => void;\n  onReject: () => void;\n  onClose: () => void;\n  className?: string;\n}\n\nexport const ActionConfirmationModal: React.FC<ActionConfirmationModalProps> = ({\n  isOpen,\n  title,\n  description,\n  actionType,\n  payload,\n  severity = 'medium',\n  onApprove,\n  onReject,\n  onClose,\n  className,\n}) => {\n  if (!isOpen) return null;\n\n  const formattedPayload =\n    typeof payload === 'string'\n      ? payload\n      : JSON.stringify(payload, null, 2);\n\n  return (\n    <AnimatePresence>\n      <div\n        className=\"fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm\"\n        onClick={onClose}\n      >\n        <motion.div\n          onClick={(e) => e.stopPropagation()}\n          initial={{ opacity: 0, scale: 0.95, y: 10 }}\n          animate={{ opacity: 1, scale: 1, y: 0 }}\n          exit={{ opacity: 0, scale: 0.95, y: 10 }}\n          transition={{ duration: 0.18 }}\n          className={cn(\n            'relative w-full max-w-lg rounded-2xl border bg-card p-6 shadow-2xl overflow-hidden',\n            severity === 'critical' && 'border-rose-500/50',\n            severity === 'medium' && 'border-amber-500/50',\n            severity === 'low' && 'border-border/80',\n            className\n          )}\n        >\n          {/* Header */}\n          <div className=\"flex items-start gap-3\">\n            <div\n              className={cn(\n                'flex h-10 w-10 items-center justify-center rounded-xl flex-shrink-0',\n                severity === 'critical' && 'bg-rose-500/15 text-rose-700 dark:text-rose-400',\n                severity === 'medium' && 'bg-amber-500/20 text-amber-900 dark:text-amber-300',\n                severity === 'low' && 'bg-blue-500/15 text-blue-800 dark:text-blue-400'\n              )}\n            >\n              {severity === 'critical' ? (\n                <AlertTriangle className=\"h-5 w-5\" />\n              ) : (\n                <ShieldAlert className=\"h-5 w-5\" />\n              )}\n            </div>\n\n            <div className=\"min-w-0 flex-1\">\n              <div className=\"flex items-center gap-2\">\n                <h3 className=\"text-sm font-semibold text-foreground\">{title}</h3>\n                <span\n                  className={cn(\n                    'text-[10px] uppercase font-mono font-bold px-1.5 py-0.5 rounded shadow-2xs',\n                    severity === 'critical' && 'bg-rose-500/20 text-rose-900 dark:text-rose-300 border border-rose-500/30',\n                    severity === 'medium' && 'bg-amber-500/25 text-amber-950 dark:text-amber-300 border border-amber-500/40',\n                    severity === 'low' && 'bg-blue-500/20 text-blue-900 dark:text-blue-300 border border-blue-500/30'\n                  )}\n                >\n                  {severity} risk\n                </span>\n              </div>\n\n              {description && (\n                <p className=\"text-xs text-muted-foreground mt-1 leading-relaxed\">\n                  {description}\n                </p>\n              )}\n            </div>\n          </div>\n\n          {/* Action Code / Payload Viewer */}\n          <div className=\"my-4 rounded-xl border border-border/60 bg-secondary/30 overflow-hidden text-xs\">\n            <div className=\"flex items-center justify-between px-3 py-1.5 bg-secondary/60 border-b border-border/40 text-[11px] font-mono text-muted-foreground\">\n              <div className=\"flex items-center gap-1.5\">\n                <Terminal className=\"h-3.5 w-3.5\" />\n                <span>{actionType}</span>\n              </div>\n            </div>\n            <pre className=\"p-3 font-mono text-[11px] leading-relaxed text-foreground overflow-x-auto max-h-56 select-text whitespace-pre-wrap break-all\">\n              {formattedPayload}\n            </pre>\n          </div>\n\n          {/* Footer Controls */}\n          <div className=\"flex items-center justify-end gap-2.5 pt-2 border-t border-border/40\">\n            <button\n              type=\"button\"\n              onClick={onReject}\n              className=\"inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-secondary border border-border/60 transition-colors\"\n            >\n              <X className=\"h-3.5 w-3.5\" />\n              Reject\n            </button>\n            <button\n              type=\"button\"\n              onClick={onApprove}\n              className={cn(\n                'inline-flex items-center gap-1.5 px-4 py-1.5 rounded-xl text-xs font-semibold text-white shadow-md transition-all',\n                severity === 'critical'\n                  ? 'bg-rose-600 hover:bg-rose-500'\n                  : 'bg-amber-600 hover:bg-amber-500'\n              )}\n            >\n              <Check className=\"h-3.5 w-3.5\" />\n              Authorize Action\n            </button>\n          </div>\n        </motion.div>\n      </div>\n    </AnimatePresence>\n  );\n};\n",
  },
  "InteractiveQuestionCard": {
    filename: "InteractiveQuestionCard.tsx",
    content: "import React, { useState } from 'react';\nimport { HelpCircle, Check, ArrowRight } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface QuestionOption {\n  id: string;\n  label: string;\n  description?: string;\n  isRecommended?: boolean;\n}\n\nexport interface InteractiveQuestionCardProps {\n  question: string;\n  description?: string;\n  options: QuestionOption[];\n  isMultiSelect?: boolean;\n  onSubmit: (selectedOptionIds: string[], customInput?: string) => void;\n  className?: string;\n}\n\nexport const InteractiveQuestionCard: React.FC<InteractiveQuestionCardProps> = ({\n  question,\n  description,\n  options,\n  isMultiSelect = false,\n  onSubmit,\n  className,\n}) => {\n  const [selectedIds, setSelectedIds] = useState<string[]>([]);\n  const [customInput, setCustomInput] = useState('');\n  const [isSubmitted, setIsSubmitted] = useState(false);\n\n  const toggleOption = (id: string) => {\n    if (isMultiSelect) {\n      setSelectedIds((prev) =>\n        prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]\n      );\n    } else {\n      setSelectedIds([id]);\n    }\n  };\n\n  const handleSubmit = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (selectedIds.length > 0 || customInput.trim()) {\n      setIsSubmitted(true);\n      onSubmit(selectedIds, customInput);\n    }\n  };\n\n  return (\n    <div\n      className={cn(\n        'my-3 p-4 rounded-xl border border-primary/30 bg-primary/5 backdrop-blur-sm shadow-sm space-y-3',\n        className\n      )}\n    >\n      <div className=\"flex items-start gap-2.5\">\n        <div className=\"flex h-6 w-6 items-center justify-center rounded-lg bg-primary/10 text-primary mt-0.5 flex-shrink-0\">\n          <HelpCircle className=\"h-3.5 w-3.5\" />\n        </div>\n        <div className=\"min-w-0\">\n          <h4 className=\"text-xs font-semibold text-foreground leading-snug\">\n            {question}\n          </h4>\n          {description && (\n            <p className=\"text-[11px] text-muted-foreground mt-0.5 leading-relaxed\">\n              {description}\n            </p>\n          )}\n        </div>\n      </div>\n\n      {/* Options List */}\n      <div className=\"space-y-1.5 pt-1\">\n        {options.map((opt) => {\n          const isSelected = selectedIds.includes(opt.id);\n          return (\n            <button\n              key={opt.id}\n              type=\"button\"\n              disabled={isSubmitted}\n              onClick={() => toggleOption(opt.id)}\n              className={cn(\n                'w-full flex items-center justify-between p-2.5 rounded-lg border text-left text-xs transition-all',\n                isSelected\n                  ? 'border-primary bg-primary/15 text-foreground font-medium shadow-2xs'\n                  : 'border-border/60 bg-card hover:bg-secondary/60 text-muted-foreground hover:text-foreground'\n              )}\n            >\n              <div className=\"min-w-0 flex-1\">\n                <div className=\"flex items-center gap-2\">\n                  <div\n                    className={cn(\n                      'flex h-4 w-4 items-center justify-center rounded border flex-shrink-0 transition-colors',\n                      isSelected\n                        ? 'border-primary bg-primary text-primary-foreground'\n                        : 'border-border bg-background'\n                    )}\n                  >\n                    {isSelected && <Check className=\"h-2.5 w-2.5 stroke-[3]\" />}\n                  </div>\n                  <span className=\"truncate text-foreground font-medium\">{opt.label}</span>\n                  {opt.isRecommended && (\n                    <span className=\"text-[9px] uppercase font-mono px-1.5 py-0.5 rounded bg-primary text-primary-foreground font-bold tracking-wider shadow-2xs\">\n                      Recommended\n                    </span>\n                  )}\n                </div>\n                {opt.description && (\n                  <p className=\"text-[10px] text-muted-foreground ml-6 mt-0.5 truncate\">\n                    {opt.description}\n                  </p>\n                )}\n              </div>\n            </button>\n          );\n        })}\n      </div>\n\n      {/* Custom write-in input & submit */}\n      {!isSubmitted && (\n        <form onSubmit={handleSubmit} className=\"flex items-center gap-2 pt-1\">\n          <input\n            type=\"text\"\n            placeholder=\"Or type custom answer...\"\n            value={customInput}\n            onChange={(e) => setCustomInput(e.target.value)}\n            className=\"flex-1 px-3 py-1.5 rounded-lg bg-background border border-border/60 text-xs text-foreground placeholder:text-muted-foreground focus:outline-hidden focus:border-primary\"\n          />\n          <button\n            type=\"submit\"\n            disabled={selectedIds.length === 0 && !customInput.trim()}\n            className=\"inline-flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-semibold bg-primary text-primary-foreground hover:opacity-90 disabled:opacity-40 transition-colors\"\n          >\n            <span>Submit</span>\n            <ArrowRight className=\"h-3 w-3\" />\n          </button>\n        </form>\n      )}\n\n      {isSubmitted && (\n        <div className=\"text-[11px] text-emerald-600 dark:text-emerald-400 flex items-center gap-1 pt-1 font-medium\">\n          <Check className=\"h-3 w-3\" />\n          <span>Response recorded</span>\n        </div>\n      )}\n    </div>\n  );\n};\n",
  },
  "FeedbackActions": {
    filename: "FeedbackActions.tsx",
    content: "import React, { useState } from 'react';\nimport { ThumbsUp, ThumbsDown, Copy, Check, RotateCcw } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface FeedbackActionsProps {\n  onFeedback?: (type: 'positive' | 'negative', comments?: string) => void;\n  onRetry?: () => void;\n  onCopy?: () => void;\n  className?: string;\n}\n\nexport const FeedbackActions: React.FC<FeedbackActionsProps> = ({\n  onFeedback,\n  onRetry,\n  onCopy,\n  className,\n}) => {\n  const [feedback, setFeedback] = useState<'positive' | 'negative' | null>(null);\n  const [copied, setCopied] = useState(false);\n\n  const handleFeedback = (type: 'positive' | 'negative') => {\n    setFeedback(type);\n    if (onFeedback) onFeedback(type);\n  };\n\n  const handleCopy = () => {\n    if (onCopy) onCopy();\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  return (\n    <div\n      className={cn(\n        'inline-flex items-center gap-1 p-1 rounded-lg bg-secondary/60 border border-border/60 text-muted-foreground text-xs',\n        className\n      )}\n    >\n      <button\n        type=\"button\"\n        onClick={() => handleFeedback('positive')}\n        className={cn(\n          'p-1 rounded-md hover:text-foreground hover:bg-background transition-colors',\n          feedback === 'positive' && 'text-emerald-700 dark:text-emerald-400 bg-emerald-500/15 font-semibold'\n        )}\n        title=\"Helpful\"\n      >\n        <ThumbsUp className=\"h-3.5 w-3.5\" />\n      </button>\n\n      <button\n        type=\"button\"\n        onClick={() => handleFeedback('negative')}\n        className={cn(\n          'p-1 rounded-md hover:text-foreground hover:bg-background transition-colors',\n          feedback === 'negative' && 'text-rose-700 dark:text-rose-400 bg-rose-500/15 font-semibold'\n        )}\n        title=\"Unhelpful\"\n      >\n        <ThumbsDown className=\"h-3.5 w-3.5\" />\n      </button>\n\n      {onCopy && (\n        <button\n          type=\"button\"\n          onClick={handleCopy}\n          className=\"p-1 rounded-md hover:text-foreground hover:bg-background/80 transition-colors\"\n          title=\"Copy response\"\n        >\n          {copied ? (\n            <Check className=\"h-3.5 w-3.5 text-emerald-500\" />\n          ) : (\n            <Copy className=\"h-3.5 w-3.5\" />\n          )}\n        </button>\n      )}\n\n      {onRetry && (\n        <button\n          type=\"button\"\n          onClick={onRetry}\n          className=\"p-1 rounded-md hover:text-foreground hover:bg-background/80 transition-colors\"\n          title=\"Regenerate response\"\n        >\n          <RotateCcw className=\"h-3.5 w-3.5\" />\n        </button>\n      )}\n    </div>\n  );\n};\n",
  },
  "ArtifactWorkspace": {
    filename: "ArtifactWorkspace.tsx",
    content: "import React, { useState } from 'react';\nimport {\n  Code,\n  Eye,\n  FileText,\n  Download,\n  Copy,\n  Check,\n  Maximize2,\n  Minimize2,\n  X,\n  Sparkles,\n} from 'lucide-react';\nimport { cn } from './cn';\nimport type { Artifact } from './types';\nimport { CodeBlock } from './CodeBlock';\nimport { StreamingText } from './StreamingText';\n\nexport interface ArtifactWorkspaceProps {\n  artifact: Artifact;\n  versions?: Artifact[];\n  onSelectVersion?: (version: number) => void;\n  onClose?: () => void;\n  className?: string;\n}\n\nexport const ArtifactWorkspace: React.FC<ArtifactWorkspaceProps> = ({\n  artifact,\n  versions = [],\n  onSelectVersion,\n  onClose,\n  className,\n}) => {\n  const [activeTab, setActiveTab] = useState<'preview' | 'code' | 'diff' | 'doc'>('code');\n  const [copied, setCopied] = useState(false);\n  const [isFullScreen, setIsFullScreen] = useState(false);\n\n  const handleCopy = () => {\n    navigator.clipboard.writeText(artifact.content);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  const handleDownload = () => {\n    const blob = new Blob([artifact.content], { type: 'text/plain;charset=utf-8' });\n    const url = URL.createObjectURL(blob);\n    const link = document.createElement('a');\n    link.href = url;\n    link.download = artifact.filename || `${artifact.title.toLowerCase().replace(/\\s+/g, '_')}.${artifact.language || 'txt'}`;\n    link.click();\n    URL.revokeObjectURL(url);\n  };\n\n  return (\n    <div\n      className={cn(\n        'flex flex-col h-full rounded-2xl border border-border/80 bg-card shadow-xl overflow-hidden',\n        isFullScreen && 'fixed inset-4 z-50 rounded-2xl shadow-2xl',\n        className\n      )}\n    >\n      {/* Workspace Header */}\n      <div className=\"flex items-center justify-between px-4 py-3 bg-secondary/40 border-b border-border/60\">\n        <div className=\"flex items-center gap-2.5 min-w-0\">\n          <div className=\"flex h-7 w-7 items-center justify-center rounded-lg bg-primary/10 text-primary\">\n            <Sparkles className=\"h-4 w-4\" />\n          </div>\n\n          <div className=\"min-w-0\">\n            <div className=\"flex items-center gap-2\">\n              <h3 className=\"text-xs font-semibold text-foreground truncate\">\n                {artifact.title}\n              </h3>\n              {artifact.version && (\n                <div className=\"flex items-center gap-1\">\n                  {versions.length > 1 && onSelectVersion ? (\n                    <select\n                      value={artifact.version}\n                      onChange={(e) => onSelectVersion(Number(e.target.value))}\n                      className=\"text-[10px] font-mono px-1.5 py-0.5 rounded bg-secondary text-foreground border border-border/40 focus:outline-hidden\"\n                    >\n                      {versions.map((v) => (\n                        <option key={v.id || v.version} value={v.version}>\n                          v{v.version}\n                        </option>\n                      ))}\n                    </select>\n                  ) : (\n                    <span className=\"text-[10px] font-mono px-1.5 py-0.2 rounded bg-secondary text-muted-foreground border border-border/40\">\n                      v{artifact.version}\n                    </span>\n                  )}\n                </div>\n              )}\n            </div>\n            {artifact.filename && (\n              <p className=\"text-[10px] font-mono text-muted-foreground truncate\">\n                {artifact.filename}\n              </p>\n            )}\n          </div>\n        </div>\n\n        {/* Action Controls */}\n        <div className=\"flex items-center gap-1.5\">\n          {/* Tab Switcher */}\n          <div className=\"flex items-center bg-background/80 p-0.5 rounded-lg border border-border/60 text-xs\">\n            {artifact.isLivePreviewable && (\n              <button\n                type=\"button\"\n                onClick={() => setActiveTab('preview')}\n                className={cn(\n                  'flex items-center gap-1 px-2.5 py-1 rounded-md transition-colors',\n                  activeTab === 'preview'\n                    ? 'bg-secondary text-foreground font-medium shadow-2xs'\n                    : 'text-muted-foreground hover:text-foreground'\n                )}\n              >\n                <Eye className=\"h-3 w-3\" />\n                <span className=\"text-[11px]\">Preview</span>\n              </button>\n            )}\n\n            <button\n              type=\"button\"\n              onClick={() => setActiveTab('code')}\n              className={cn(\n                'flex items-center gap-1 px-2.5 py-1 rounded-md transition-colors',\n                activeTab === 'code'\n                  ? 'bg-secondary text-foreground font-medium shadow-2xs'\n                  : 'text-muted-foreground hover:text-foreground'\n              )}\n            >\n              <Code className=\"h-3 w-3\" />\n              <span className=\"text-[11px]\">Code</span>\n            </button>\n\n            {artifact.type === 'markdown' && (\n              <button\n                type=\"button\"\n                onClick={() => setActiveTab('doc')}\n                className={cn(\n                  'flex items-center gap-1 px-2.5 py-1 rounded-md transition-colors',\n                  activeTab === 'doc'\n                    ? 'bg-secondary text-foreground font-medium shadow-2xs'\n                    : 'text-muted-foreground hover:text-foreground'\n                )}\n              >\n                <FileText className=\"h-3 w-3\" />\n                <span className=\"text-[11px]\">Doc</span>\n              </button>\n            )}\n          </div>\n\n          <button\n            type=\"button\"\n            onClick={handleCopy}\n            className=\"p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n            title=\"Copy content\"\n          >\n            {copied ? (\n              <Check className=\"h-3.5 w-3.5 text-emerald-500\" />\n            ) : (\n              <Copy className=\"h-3.5 w-3.5\" />\n            )}\n          </button>\n\n          <button\n            type=\"button\"\n            onClick={handleDownload}\n            className=\"p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n            title=\"Download file\"\n          >\n            <Download className=\"h-3.5 w-3.5\" />\n          </button>\n\n          <button\n            type=\"button\"\n            onClick={() => setIsFullScreen(!isFullScreen)}\n            className=\"p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n            title={isFullScreen ? 'Exit Fullscreen' : 'Fullscreen'}\n          >\n            {isFullScreen ? (\n              <Minimize2 className=\"h-3.5 w-3.5\" />\n            ) : (\n              <Maximize2 className=\"h-3.5 w-3.5\" />\n            )}\n          </button>\n\n          {onClose && (\n            <button\n              type=\"button\"\n              onClick={onClose}\n              className=\"p-1.5 rounded-lg text-muted-foreground hover:text-foreground hover:bg-secondary transition-colors\"\n              title=\"Close artifact\"\n            >\n              <X className=\"h-3.5 w-3.5\" />\n            </button>\n          )}\n        </div>\n      </div>\n\n      {/* Main Content Area */}\n      <div className=\"flex-1 overflow-y-auto p-4 bg-background/50\">\n        {activeTab === 'preview' && (\n          <div className=\"h-full min-h-[320px] rounded-xl border border-border/60 bg-background p-4 shadow-inner flex items-center justify-center\">\n            {artifact.type === 'svg' || artifact.type === 'html' ? (\n              <div\n                className=\"w-full h-full flex items-center justify-center\"\n                dangerouslySetInnerHTML={{ __html: artifact.content }}\n              />\n            ) : (\n              <div className=\"text-center text-muted-foreground text-xs\">\n                <p>Live interactive component rendering preview</p>\n              </div>\n            )}\n          </div>\n        )}\n\n        {activeTab === 'code' && (\n          <CodeBlock\n            code={artifact.content}\n            language={artifact.language || 'typescript'}\n            filename={artifact.filename}\n            className=\"my-0 h-full\"\n          />\n        )}\n\n        {activeTab === 'doc' && (\n          <div className=\"prose prose-sm dark:prose-invert max-w-none p-4 rounded-xl border border-border/60 bg-card\">\n            <StreamingText content={artifact.content} />\n          </div>\n        )}\n      </div>\n    </div>\n  );\n};\n",
  },
  "CodeBlock": {
    filename: "CodeBlock.tsx",
    content: "import React, { useState } from 'react';\nimport { Copy, Check, FileCode, Maximize2, Minimize2 } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface CodeBlockProps {\n  code: string;\n  language?: string;\n  filename?: string;\n  showLineNumbers?: boolean;\n  className?: string;\n}\n\nexport const CodeBlock: React.FC<CodeBlockProps> = ({\n  code,\n  language = 'typescript',\n  filename,\n  showLineNumbers = true,\n  className,\n}) => {\n  const [copied, setCopied] = useState(false);\n  const [isFullScreen, setIsFullScreen] = useState(false);\n\n  const lines = code.split('\\n');\n\n  const handleCopy = () => {\n    navigator.clipboard.writeText(code);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  return (\n    <div\n      className={cn(\n        'group my-3 rounded-xl border border-border/60 bg-neutral-950 text-neutral-100 font-mono text-xs overflow-hidden shadow-md transition-all',\n        isFullScreen && 'fixed inset-4 z-50 my-0 shadow-2xl flex flex-col',\n        className\n      )}\n    >\n      {/* Header Bar */}\n      <div className=\"flex items-center justify-between px-4 py-2 bg-neutral-900 border-b border-neutral-800 text-[11px] select-none\">\n        <div className=\"flex items-center gap-2 text-neutral-400\">\n          <FileCode className=\"h-3.5 w-3.5 text-neutral-500\" />\n          <span className=\"font-sans font-medium text-neutral-200\">\n            {filename || `${language} snippet`}\n          </span>\n          <span className=\"uppercase text-[9px] px-1.5 py-0.2 rounded bg-neutral-800 text-neutral-400 font-mono\">\n            {language}\n          </span>\n        </div>\n\n        <div className=\"flex items-center gap-1.5\">\n          <button\n            type=\"button\"\n            onClick={handleCopy}\n            className=\"flex items-center gap-1 px-2 py-1 rounded-md text-neutral-400 hover:text-neutral-100 hover:bg-neutral-800 transition-colors\"\n            title=\"Copy code\"\n          >\n            {copied ? (\n              <>\n                <Check className=\"h-3 w-3 text-emerald-400\" />\n                <span className=\"text-[10px] text-emerald-400\">Copied</span>\n              </>\n            ) : (\n              <>\n                <Copy className=\"h-3 w-3\" />\n                <span className=\"text-[10px]\">Copy</span>\n              </>\n            )}\n          </button>\n\n          <button\n            type=\"button\"\n            onClick={() => setIsFullScreen(!isFullScreen)}\n            className=\"p-1 rounded-md text-neutral-400 hover:text-neutral-100 hover:bg-neutral-800 transition-colors\"\n            title={isFullScreen ? 'Exit Fullscreen' : 'Fullscreen'}\n          >\n            {isFullScreen ? (\n              <Minimize2 className=\"h-3.5 w-3.5\" />\n            ) : (\n              <Maximize2 className=\"h-3.5 w-3.5\" />\n            )}\n          </button>\n        </div>\n      </div>\n\n      {/* Code Body */}\n      <div className=\"p-3.5 overflow-x-auto select-text flex-1\">\n        <pre className=\"flex text-xs leading-relaxed\">\n          {showLineNumbers && (\n            <div className=\"flex flex-col text-neutral-600 select-none pr-4 text-right border-r border-neutral-800 mr-4 font-mono text-[11px]\">\n              {lines.map((_, i) => (\n                <span key={i}>{i + 1}</span>\n              ))}\n            </div>\n          )}\n          <code className=\"text-neutral-200 flex-1 whitespace-pre\">{code}</code>\n        </pre>\n      </div>\n    </div>\n  );\n};\n",
  },
  "DiffViewer": {
    filename: "DiffViewer.tsx",
    content: "import React from 'react';\nimport { GitCompare } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface DiffViewerProps {\n  diffText: string;\n  filename?: string;\n  className?: string;\n}\n\nexport const DiffViewer: React.FC<DiffViewerProps> = ({\n  diffText,\n  filename,\n  className,\n}) => {\n  const lines = diffText.split('\\n');\n\n  return (\n    <div\n      className={cn(\n        'my-3 rounded-xl border border-border/60 bg-neutral-950 text-neutral-100 font-mono text-xs overflow-hidden shadow-md',\n        className\n      )}\n    >\n      {/* Diff Header */}\n      <div className=\"flex items-center justify-between px-4 py-2 bg-neutral-900 border-b border-neutral-800 text-[11px] select-none\">\n        <div className=\"flex items-center gap-2 text-neutral-300\">\n          <GitCompare className=\"h-3.5 w-3.5 text-primary\" />\n          <span className=\"font-sans font-medium\">{filename || 'File Diff'}</span>\n        </div>\n      </div>\n\n      {/* Diff Lines Body */}\n      <div className=\"p-2 overflow-x-auto select-text font-mono text-[11px] leading-relaxed\">\n        {lines.map((line, idx) => {\n          const isAdd = line.startsWith('+');\n          const isDel = line.startsWith('-');\n          const isHunk = line.startsWith('@@');\n\n          return (\n            <div\n              key={idx}\n              className={cn(\n                'flex items-center px-2 py-0.5 rounded-xs transition-colors',\n                isAdd && 'bg-emerald-950/40 text-emerald-300 border-l-2 border-emerald-500',\n                isDel && 'bg-rose-950/40 text-rose-300 border-l-2 border-rose-500',\n                isHunk && 'bg-neutral-900 text-neutral-400 italic my-1 font-sans text-[10px]',\n                !isAdd && !isDel && !isHunk && 'text-neutral-300'\n              )}\n            >\n              <div className=\"w-5 select-none text-neutral-500 text-center flex-shrink-0 mr-2\">\n                {isAdd ? '+' : isDel ? '-' : ''}\n              </div>\n              <span className=\"whitespace-pre flex-1\">{line.replace(/^[+-]/, '')}</span>\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n};\n",
  },
  "TerminalStream": {
    filename: "TerminalStream.tsx",
    content: "import React, { useRef, useEffect } from 'react';\nimport { Terminal, Square, CheckCircle2, AlertCircle, Loader2, Copy, Check } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface TerminalStreamProps {\n  command: string;\n  output: string;\n  status?: 'running' | 'completed' | 'failed' | 'idle';\n  exitCode?: number;\n  onInterrupt?: () => void;\n  className?: string;\n}\n\nexport const TerminalStream: React.FC<TerminalStreamProps> = ({\n  command,\n  output,\n  status = 'completed',\n  exitCode,\n  onInterrupt,\n  className,\n}) => {\n  const terminalRef = useRef<HTMLDivElement>(null);\n  const [copied, setCopied] = React.useState(false);\n\n  // Auto-scroll as terminal output streams\n  useEffect(() => {\n    if (terminalRef.current) {\n      terminalRef.current.scrollTop = terminalRef.current.scrollHeight;\n    }\n  }, [output]);\n\n  const handleCopy = () => {\n    navigator.clipboard.writeText(`$ ${command}\\n${output}`);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  return (\n    <div\n      className={cn(\n        'my-3 rounded-xl border border-neutral-800 bg-[#09090b] text-neutral-100 font-mono text-xs overflow-hidden shadow-lg',\n        status === 'running' && 'border-cyan-500/40 shadow-cyan-500/5',\n        className\n      )}\n    >\n      {/* Terminal Titlebar */}\n      <div className=\"flex items-center justify-between px-3.5 py-2 bg-neutral-900 border-b border-neutral-800 select-none\">\n        <div className=\"flex items-center gap-2\">\n          <div className=\"flex items-center gap-1.5 mr-1\">\n            <div className=\"h-2.5 w-2.5 rounded-full bg-rose-500/80\" />\n            <div className=\"h-2.5 w-2.5 rounded-full bg-amber-500/80\" />\n            <div className=\"h-2.5 w-2.5 rounded-full bg-emerald-500/80\" />\n          </div>\n          <Terminal className=\"h-3.5 w-3.5 text-neutral-400\" />\n          <span className=\"text-[11px] text-neutral-300 font-medium truncate max-w-xs font-sans\">\n            {command || 'bash'}\n          </span>\n        </div>\n\n        <div className=\"flex items-center gap-2\">\n          {status === 'running' && (\n            <div className=\"flex items-center gap-1 text-[10px] text-cyan-400\">\n              <Loader2 className=\"h-2.5 w-2.5 animate-spin\" />\n              <span>Running</span>\n            </div>\n          )}\n\n          {status === 'completed' && (\n            <div className=\"flex items-center gap-1 text-[10px] text-emerald-400\">\n              <CheckCircle2 className=\"h-2.5 w-2.5\" />\n              <span>Exited (0)</span>\n            </div>\n          )}\n\n          {status === 'failed' && (\n            <div className=\"flex items-center gap-1 text-[10px] text-rose-400\">\n              <AlertCircle className=\"h-2.5 w-2.5\" />\n              <span>Failed ({exitCode ?? 1})</span>\n            </div>\n          )}\n\n          {status === 'running' && onInterrupt && (\n            <button\n              type=\"button\"\n              onClick={onInterrupt}\n              className=\"flex items-center gap-1 px-1.5 py-0.5 rounded bg-rose-500/20 hover:bg-rose-500/30 text-rose-300 text-[10px] font-sans transition-colors\"\n            >\n              <Square className=\"h-2.5 w-2.5 fill-current\" />\n              <span>Kill</span>\n            </button>\n          )}\n\n          <button\n            type=\"button\"\n            onClick={handleCopy}\n            className=\"p-1 rounded text-neutral-400 hover:text-neutral-200 hover:bg-neutral-800 transition-colors\"\n            title=\"Copy command & output\"\n          >\n            {copied ? (\n              <Check className=\"h-3 w-3 text-emerald-400\" />\n            ) : (\n              <Copy className=\"h-3 w-3\" />\n            )}\n          </button>\n        </div>\n      </div>\n\n      {/* Terminal Viewport */}\n      <div\n        ref={terminalRef}\n        className=\"p-3.5 max-h-72 overflow-y-auto font-mono text-[11px] leading-relaxed select-text space-y-1\"\n      >\n        <div className=\"flex items-center gap-1.5 text-neutral-400 pb-1\">\n          <span className=\"text-emerald-400 font-bold\">$</span>\n          <span className=\"text-neutral-100 font-semibold\">{command}</span>\n        </div>\n\n        <pre className=\"text-neutral-300 whitespace-pre-wrap break-all\">\n          {output}\n        </pre>\n\n        {status === 'running' && (\n          <span className=\"inline-block h-3.5 w-1.5 bg-neutral-300 animate-pulse align-middle ml-0.5\" />\n        )}\n      </div>\n    </div>\n  );\n};\n",
  },
  "AgentStatusBadge": {
    filename: "AgentStatusBadge.tsx",
    content: "import React from 'react';\nimport { Sparkles, Loader2, Globe, FileCode, ShieldAlert, CheckCircle2, Pause } from 'lucide-react';\nimport { cn } from './cn';\n\nexport type AgentState =\n  | 'idle'\n  | 'thinking'\n  | 'searching'\n  | 'coding'\n  | 'awaiting_approval'\n  | 'completed'\n  | 'paused';\n\nexport interface AgentStatusBadgeProps {\n  state: AgentState;\n  variant?: 'solid' | 'subtle';\n  customLabel?: string;\n  className?: string;\n}\n\nexport const AgentStatusBadge: React.FC<AgentStatusBadgeProps> = ({\n  state,\n  variant = 'subtle',\n  customLabel,\n  className,\n}) => {\n  const getBadgeConfig = () => {\n    const isSolid = variant === 'solid';\n\n    switch (state) {\n      case 'thinking':\n        return {\n          icon: (\n            <Loader2\n              className={cn(\n                'h-3 w-3 animate-spin',\n                isSolid ? 'text-primary-foreground' : 'text-primary'\n              )}\n            />\n          ),\n          label: customLabel || 'Reasoning...',\n          classes: isSolid\n            ? 'bg-primary text-primary-foreground border-primary/40 font-semibold shadow-xs'\n            : 'bg-primary/15 text-foreground border-primary/30 font-medium',\n          dot: isSolid ? 'bg-primary-foreground' : 'bg-primary',\n        };\n      case 'searching':\n        return {\n          icon: <Globe className=\"h-3 w-3 animate-pulse\" />,\n          label: customLabel || 'Browsing web...',\n          classes: isSolid\n            ? 'bg-cyan-500 text-cyan-950 border-cyan-400 font-semibold shadow-xs'\n            : 'bg-cyan-500/15 text-cyan-800 dark:text-cyan-300 border-cyan-500/30',\n          dot: isSolid ? 'bg-cyan-950' : 'bg-cyan-500',\n        };\n      case 'coding':\n        return {\n          icon: <FileCode className=\"h-3 w-3 animate-pulse\" />,\n          label: customLabel || 'Synthesizing code...',\n          classes: isSolid\n            ? 'bg-blue-600 text-white border-blue-500 font-semibold shadow-xs'\n            : 'bg-blue-500/15 text-blue-800 dark:text-blue-300 border-blue-500/30',\n          dot: isSolid ? 'bg-white' : 'bg-blue-500',\n        };\n      case 'awaiting_approval':\n        return {\n          icon: <ShieldAlert className=\"h-3 w-3\" />,\n          label: customLabel || 'Awaiting approval',\n          classes: isSolid\n            ? 'bg-amber-500 text-amber-950 border-amber-400 font-semibold shadow-xs animate-pulse'\n            : 'bg-amber-500/20 text-amber-900 dark:text-amber-300 border-amber-500/40 font-medium animate-pulse',\n          dot: isSolid ? 'bg-amber-950' : 'bg-amber-500',\n        };\n      case 'completed':\n        return {\n          icon: <CheckCircle2 className=\"h-3 w-3\" />,\n          label: customLabel || 'Task completed',\n          classes: isSolid\n            ? 'bg-emerald-600 text-white border-emerald-500 font-semibold shadow-xs'\n            : 'bg-emerald-500/15 text-emerald-800 dark:text-emerald-300 border-emerald-500/30',\n          dot: isSolid ? 'bg-white' : 'bg-emerald-500',\n        };\n      case 'paused':\n        return {\n          icon: <Pause className=\"h-3 w-3\" />,\n          label: customLabel || 'Paused',\n          classes: 'bg-secondary text-muted-foreground border-border/60',\n          dot: 'bg-muted-foreground',\n        };\n      case 'idle':\n      default:\n        return {\n          icon: <Sparkles className=\"h-3 w-3 text-muted-foreground\" />,\n          label: customLabel || 'Agent Ready',\n          classes: 'bg-secondary/80 text-foreground/80 border-border/60',\n          dot: 'bg-muted-foreground/60',\n        };\n    }\n  };\n\n  const config = getBadgeConfig();\n\n  return (\n    <div\n      className={cn(\n        'inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-mono border shadow-2xs transition-all',\n        config.classes,\n        className\n      )}\n    >\n      <span className=\"relative flex h-2 w-2\">\n        {state !== 'idle' && state !== 'completed' && state !== 'paused' && (\n          <span\n            className={cn(\n              'animate-ping absolute inline-flex h-full w-full rounded-full opacity-75',\n              config.dot\n            )}\n          />\n        )}\n        <span\n          className={cn('relative inline-flex rounded-full h-2 w-2', config.dot)}\n        />\n      </span>\n\n      {config.icon}\n      <span className=\"font-medium text-[11px]\">{config.label}</span>\n    </div>\n  );\n};\n",
  },
  "TokenUsageMeter": {
    filename: "TokenUsageMeter.tsx",
    content: "import React from 'react';\nimport { Cpu, DollarSign } from 'lucide-react';\nimport { cn } from './cn';\nimport type { TokenUsage } from './types';\n\nexport interface TokenUsageMeterProps {\n  usage: TokenUsage;\n  maxTokens?: number;\n  className?: string;\n}\n\nexport const TokenUsageMeter: React.FC<TokenUsageMeterProps> = ({\n  usage,\n  maxTokens = 128000,\n  className,\n}) => {\n  const total = usage.total || (usage.prompt || 0) + (usage.completion || 0);\n  const percent = Math.min(Math.round((total / maxTokens) * 100), 100);\n\n  return (\n    <div\n      className={cn(\n        'inline-flex items-center gap-3 px-3 py-1.5 rounded-xl border border-border/60 bg-secondary/30 text-xs font-mono',\n        className\n      )}\n    >\n      <div className=\"flex items-center gap-1.5 text-muted-foreground\">\n        <Cpu className=\"h-3.5 w-3.5 text-primary\" />\n        <span className=\"font-semibold text-foreground\">\n          {(total / 1000).toFixed(1)}k\n        </span>\n        <span className=\"text-[10px] text-muted-foreground\">\n          / {(maxTokens / 1000).toFixed(0)}k toks\n        </span>\n      </div>\n\n      {/* Progress Bar */}\n      <div className=\"w-16 h-1.5 rounded-full bg-secondary border border-border/40 overflow-hidden hidden sm:block\">\n        <div\n          className={cn(\n            'h-full rounded-full transition-all duration-300',\n            percent > 85 ? 'bg-rose-500' : percent > 60 ? 'bg-amber-500' : 'bg-primary'\n          )}\n          style={{ width: `${percent}%` }}\n        />\n      </div>\n\n      {usage.costUsd !== undefined && (\n        <div className=\"hidden md:flex items-center gap-0.5 text-muted-foreground border-l border-border/40 pl-2\">\n          <DollarSign className=\"h-3 w-3 text-emerald-500\" />\n          <span className=\"text-[11px] font-medium text-foreground\">\n            {usage.costUsd.toFixed(4)}\n          </span>\n        </div>\n      )}\n    </div>\n  );\n};\n",
  },
  "ThemeColorPicker": {
    filename: "ThemeColorPicker.tsx",
    content: "import React, { useState } from 'react';\nimport { Palette, Copy, Check, MessageSquare } from 'lucide-react';\nimport { cn } from './cn';\n\nexport interface ThemeColorPreset {\n  name: string;\n  hue: number;\n  sat?: number;\n  light?: number;\n  hex?: string;\n}\n\nexport const defaultColorPresets: ThemeColorPreset[] = [\n  { name: 'Violet', hue: 265, sat: 85, light: 60, hex: '#8b5cf6' },\n  { name: 'Electric Indigo', hue: 235, sat: 85, light: 60, hex: '#6366f1' },\n  { name: 'Cyber Cyan', hue: 195, sat: 90, light: 50, hex: '#0ea5e9' },\n  { name: 'Neon Lime', hue: 85, sat: 85, light: 55, hex: '#84cc16' },\n  { name: 'Emerald Matrix', hue: 155, sat: 80, light: 45, hex: '#10b981' },\n  { name: 'Amber Gold', hue: 40, sat: 95, light: 52, hex: '#f59e0b' },\n  { name: 'Sunset Orange', hue: 25, sat: 90, light: 55, hex: '#f97316' },\n  { name: 'Crimson Rose', hue: 350, sat: 85, light: 58, hex: '#f43f5e' },\n  { name: 'Neon Fuchsia', hue: 305, sat: 85, light: 60, hex: '#d946ef' },\n];\n\n// Helper: HSL to sRGB\nexport function hslToRgb(h: number, s: number, l: number): [number, number, number] {\n  s /= 100;\n  l /= 100;\n  const k = (n: number) => (n + h / 30) % 12;\n  const a = s * Math.min(l, 1 - l);\n  const f = (n: number) => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));\n  return [Math.round(f(0) * 255), Math.round(f(8) * 255), Math.round(f(4) * 255)];\n}\n\n// Helper: WCAG 2.1 relative luminance\nexport function getLuminance(r: number, g: number, b: number): number {\n  const [rs, gs, bs] = [r, g, b].map((val) => {\n    const s = val / 255;\n    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);\n  });\n  return 0.2126 * rs + 0.7152 * gs + 0.0722 * bs;\n}\n\n// Helper: Calculate contrast metrics\nexport function getContrastMetrics(h: number, s: number, l: number) {\n  const [r, g, b] = hslToRgb(h, s, l);\n  const lum = getLuminance(r, g, b);\n  const contrastWithBlack = (lum + 0.05) / 0.05;\n  const contrastWithWhite = 1.05 / (lum + 0.05);\n  const isLightBackground = contrastWithBlack > contrastWithWhite;\n  const ratio = Math.max(contrastWithBlack, contrastWithWhite).toFixed(1);\n  const foregroundHsl = isLightBackground ? '240 10% 3.9%' : '0 0% 100%';\n  const foregroundHex = isLightBackground ? '#09090b' : '#ffffff';\n\n  return {\n    luminance: lum,\n    contrastWithBlack,\n    contrastWithWhite,\n    isLightBackground,\n    ratio,\n    foregroundHsl,\n    foregroundHex,\n  };\n}\n\nexport interface ThemeColorPickerProps {\n  hue: number;\n  saturation?: number;\n  lightness?: number;\n  onChangeHue?: (hue: number) => void;\n  onChangeSaturation?: (saturation: number) => void;\n  onChangeLightness?: (lightness: number) => void;\n  onChangeHsl?: (hue: number, saturation: number, lightness: number) => void;\n  presets?: ThemeColorPreset[];\n  showSaturation?: boolean;\n  showLightness?: boolean;\n  showPresets?: boolean;\n  showContrastPreview?: boolean;\n  showCopyCss?: boolean;\n  mode?: 'popover' | 'inline';\n  messageVariant?: 'solid' | 'subtle' | 'neutral' | 'bordered';\n  onChangeMessageVariant?: (variant: 'solid' | 'subtle' | 'neutral' | 'bordered') => void;\n  title?: string;\n  triggerLabel?: string;\n  className?: string;\n  popoverClassName?: string;\n}\n\nexport const ThemeColorPicker: React.FC<ThemeColorPickerProps> = ({\n  hue,\n  saturation = 85,\n  lightness = 60,\n  onChangeHue,\n  onChangeSaturation,\n  onChangeLightness,\n  onChangeHsl,\n  presets = defaultColorPresets,\n  showSaturation = true,\n  showLightness = true,\n  showPresets = true,\n  showContrastPreview = true,\n  showCopyCss = true,\n  mode = 'popover',\n  messageVariant,\n  onChangeMessageVariant,\n  title = 'Theme & Contrast Studio',\n  triggerLabel,\n  className,\n  popoverClassName,\n}) => {\n  const [isOpen, setIsOpen] = useState(false);\n  const [copied, setCopied] = useState(false);\n\n  const metrics = getContrastMetrics(hue, saturation, lightness);\n\n  const handleUpdate = (newH: number, newS: number, newL: number) => {\n    if (onChangeHsl) {\n      onChangeHsl(newH, newS, newL);\n    }\n    if (newH !== hue && onChangeHue) onChangeHue(newH);\n    if (newS !== saturation && onChangeSaturation) onChangeSaturation(newS);\n    if (newL !== lightness && onChangeLightness) onChangeLightness(newL);\n  };\n\n  const handleCopyCss = () => {\n    const cssCode = `:root {\\n  --primary-hue: ${hue};\\n  --primary-sat: ${saturation}%;\\n  --primary-light: ${lightness}%;\\n  --primary: ${hue} ${saturation}% ${lightness}%;\\n  --primary-foreground: ${metrics.foregroundHsl};\\n}`;\n    navigator.clipboard.writeText(cssCode);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  };\n\n  const pickerPanel = (\n    <div\n      className={cn(\n        'rounded-2xl border border-border/80 bg-popover/95 backdrop-blur-xl shadow-2xl p-4 space-y-4 text-foreground select-none',\n        mode === 'popover' ? 'w-84 sm:w-96' : 'w-full',\n        popoverClassName\n      )}\n    >\n      {/* Panel Header */}\n      <div className=\"flex items-center justify-between border-b border-border/40 pb-2.5\">\n        <div className=\"flex items-center gap-2\">\n          <Palette className=\"h-4 w-4 text-primary\" />\n          <span className=\"text-xs font-bold text-foreground\">{title}</span>\n        </div>\n        <span className=\"text-[10px] font-mono px-1.5 py-0.5 rounded bg-secondary text-muted-foreground\">\n          HSL({hue}°, {saturation}%, {lightness}%)\n        </span>\n      </div>\n\n      {/* Smart Contrast & Live Sample Preview */}\n      {showContrastPreview && (\n        <div className=\"flex items-center justify-between p-2.5 rounded-xl bg-secondary/50 border border-border/60 text-xs\">\n          <div className=\"flex items-center gap-2\">\n            <div\n              className=\"px-2 py-1 rounded-md text-[11px] font-bold shadow-xs transition-colors\"\n              style={{\n                backgroundColor: `hsl(${hue}, ${saturation}%, ${lightness}%)`,\n                color: metrics.foregroundHex,\n              }}\n            >\n              Sample Button\n            </div>\n          </div>\n          <div className=\"flex items-center gap-1.5 font-mono text-[11px]\">\n            <span className=\"text-muted-foreground\">Contrast:</span>\n            <span className=\"font-bold text-foreground\">{metrics.ratio}:1</span>\n            <span className=\"text-[10px] px-1.5 py-0.5 rounded bg-primary text-primary-foreground font-bold shadow-2xs\">\n              {metrics.isLightBackground ? 'Black text' : 'White text'}\n            </span>\n          </div>\n        </div>\n      )}\n\n      {/* Message Bubble Contrast Style Selector */}\n      {onChangeMessageVariant && messageVariant && (\n        <div className=\"space-y-1.5\">\n          <div className=\"flex items-center justify-between text-[11px]\">\n            <span className=\"font-semibold text-foreground flex items-center gap-1.5\">\n              <MessageSquare className=\"h-3 w-3 text-primary\" />\n              Message Bubble Contrast Mode\n            </span>\n            <span className=\"text-[10px] font-mono text-muted-foreground\">\n              {messageVariant}\n            </span>\n          </div>\n          <div className=\"grid grid-cols-4 gap-1 p-1 bg-secondary/60 rounded-xl border border-border/60 text-[10px]\">\n            {(\n              [\n                { id: 'solid', label: 'Solid' },\n                { id: 'subtle', label: 'Subtle' },\n                { id: 'neutral', label: 'Neutral' },\n                { id: 'bordered', label: 'Bordered' },\n              ] as const\n            ).map((v) => (\n              <button\n                key={v.id}\n                type=\"button\"\n                onClick={() => onChangeMessageVariant(v.id)}\n                className={`py-1 rounded-lg font-medium transition-all ${\n                  messageVariant === v.id\n                    ? 'bg-primary text-primary-foreground shadow-xs font-bold'\n                    : 'text-muted-foreground hover:text-foreground'\n                }`}\n              >\n                {v.label}\n              </button>\n            ))}\n          </div>\n        </div>\n      )}\n\n      {/* 1. Hue Slider (0° - 360°) */}\n      <div className=\"space-y-1.5\">\n        <div className=\"flex items-center justify-between text-[11px]\">\n          <span className=\"font-medium text-foreground\">Hue</span>\n          <span className=\"font-mono text-foreground font-bold\">{hue}°</span>\n        </div>\n        <input\n          type=\"range\"\n          min=\"0\"\n          max=\"360\"\n          value={hue}\n          onChange={(e) => handleUpdate(Number(e.target.value), saturation, lightness)}\n          className=\"hue-slider w-full\"\n          title=\"Hue Slider (0° - 360°)\"\n        />\n      </div>\n\n      {/* 2. Saturation Slider (0% - 100%) */}\n      {showSaturation && (\n        <div className=\"space-y-1.5\">\n          <div className=\"flex items-center justify-between text-[11px]\">\n            <span className=\"font-medium text-foreground\">Saturation</span>\n            <span className=\"font-mono text-foreground font-bold\">{saturation}%</span>\n          </div>\n          <input\n            type=\"range\"\n            min=\"0\"\n            max=\"100\"\n            value={saturation}\n            onChange={(e) => handleUpdate(hue, Number(e.target.value), lightness)}\n            className=\"sat-slider w-full\"\n            title=\"Saturation Slider (0% - 100%)\"\n            style={{\n              background: `linear-gradient(to right, hsl(${hue}, 0%, ${lightness}%), hsl(${hue}, 100%, ${lightness}%))`,\n            }}\n          />\n        </div>\n      )}\n\n      {/* 3. Lightness Slider (15% - 85%) */}\n      {showLightness && (\n        <div className=\"space-y-1.5\">\n          <div className=\"flex items-center justify-between text-[11px]\">\n            <span className=\"font-medium text-foreground\">Lightness</span>\n            <span className=\"font-mono text-foreground font-bold\">{lightness}%</span>\n          </div>\n          <input\n            type=\"range\"\n            min=\"15\"\n            max=\"85\"\n            value={lightness}\n            onChange={(e) => handleUpdate(hue, saturation, Number(e.target.value))}\n            className=\"light-slider w-full\"\n            title=\"Lightness Slider (15% - 85%)\"\n            style={{\n              background: `linear-gradient(to right, hsl(${hue}, ${saturation}%, 15%), hsl(${hue}, ${saturation}%, 50%), hsl(${hue}, ${saturation}%, 85%))`,\n            }}\n          />\n        </div>\n      )}\n\n      {/* Color Preset Swatches */}\n      {showPresets && presets.length > 0 && (\n        <div className=\"space-y-1.5 pt-1\">\n          <span className=\"text-[10px] font-mono uppercase tracking-wider text-muted-foreground\">\n            Preset Palettes\n          </span>\n          <div className=\"grid grid-cols-3 gap-1.5\">\n            {presets.map((preset) => (\n              <button\n                key={preset.name}\n                type=\"button\"\n                onClick={() =>\n                  handleUpdate(\n                    preset.hue,\n                    preset.sat ?? saturation,\n                    preset.light ?? lightness\n                  )\n                }\n                className={`flex items-center gap-1.5 p-1.5 rounded-lg border text-[11px] transition-all ${\n                  hue === preset.hue &&\n                  saturation === (preset.sat ?? saturation) &&\n                  lightness === (preset.light ?? lightness)\n                    ? 'border-primary bg-primary/10 font-bold text-foreground'\n                    : 'border-border/60 hover:bg-secondary/60 text-muted-foreground hover:text-foreground'\n                }`}\n              >\n                <div\n                  className=\"h-3.5 w-3.5 rounded-full border border-background shadow-xs flex-shrink-0\"\n                  style={{\n                    backgroundColor:\n                      preset.hex ||\n                      `hsl(${preset.hue}, ${preset.sat || 85}%, ${preset.light || 60}%)`,\n                  }}\n                />\n                <span className=\"truncate\">{preset.name}</span>\n              </button>\n            ))}\n          </div>\n        </div>\n      )}\n\n      {/* Copy CSS Variables Footer */}\n      {showCopyCss && (\n        <div className=\"pt-2 border-t border-border/40 flex items-center justify-between\">\n          <span className=\"text-[10px] text-muted-foreground font-mono truncate max-w-[200px]\">\n            --primary: {hue} {saturation}% {lightness}%;\n          </span>\n          <button\n            type=\"button\"\n            onClick={handleCopyCss}\n            className=\"inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium bg-secondary hover:bg-secondary/80 text-foreground transition-colors\"\n          >\n            {copied ? (\n              <>\n                <Check className=\"h-3 w-3 text-emerald-500\" />\n                <span className=\"text-[11px] text-emerald-500 font-medium\">Copied</span>\n              </>\n            ) : (\n              <>\n                <Copy className=\"h-3 w-3\" />\n                <span className=\"text-[11px]\">Copy CSS</span>\n              </>\n            )}\n          </button>\n        </div>\n      )}\n    </div>\n  );\n\n  if (mode === 'inline') {\n    return <div className={cn('w-full', className)}>{pickerPanel}</div>;\n  }\n\n  return (\n    <div className={cn('relative inline-block text-left', className)}>\n      {/* Trigger Button */}\n      <button\n        type=\"button\"\n        onClick={() => setIsOpen(!isOpen)}\n        className=\"inline-flex items-center gap-2 px-2.5 py-1.5 rounded-xl bg-secondary/70 hover:bg-secondary border border-border/60 text-xs font-medium text-foreground transition-all shadow-2xs\"\n        title=\"Customize Theme & Color Contrast\"\n      >\n        <div\n          className=\"h-3.5 w-3.5 rounded-full border border-background shadow-xs transition-colors flex-shrink-0\"\n          style={{ backgroundColor: `hsl(${hue}, ${saturation}%, ${lightness}%)` }}\n        />\n        <span className=\"hidden sm:inline font-mono text-[11px]\">\n          {triggerLabel || `${hue}° / ${lightness}%`}\n        </span>\n        <Palette className=\"h-3.5 w-3.5 text-muted-foreground\" />\n      </button>\n\n      {/* Popover Floating Overlay */}\n      {isOpen && (\n        <>\n          <div className=\"fixed inset-0 z-40\" onClick={() => setIsOpen(false)} />\n          <div className=\"absolute right-0 top-full mt-2 z-50\">{pickerPanel}</div>\n        </>\n      )}\n    </div>\n  );\n};\n",
  },
};
